	},
	["Priestess Josetta"] = {
		["I trust the Light is with you, $n. Is there something that I can I help you with?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["Do not turn your back on the Light, $c, it may be the one thing that saves you some day."] = "120875f188ac12780f811009b51a783b",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "768f0928588ebe52253715a9f6b21ad7",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "cc24e4d0a2cf60bd7ee0678b7a460964"
	},
	["Katie Hunter"] = {
		["Years of quality breeding techniques and plenty of care allow me the privilege of showing you these horses!  Please, take your time as you consider them for your mount.  A horse is a companion for the ages, friend.  Don't sell yourself short - get your steed here today!"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
		["Sorry, but I am not disposed to sell horses to any individual who is not considered to be at least exalted to the Kingdom of Stormwind.  These steeds are the finest you'll find anywhere, and we certainly wouldn't want them in the hands of our enemies.$B$BNot saying you're an enemy, of course... just earn the trust of Stormwind and then we can do business."] = "33c0e9087e12555f8dc52cc2a68cccb1"
	},
	["Drusilla La Salle"] = {
		["The arcane only corrupts those who are weak. Even if you do not follow the path of the warlock, you would do well to remember that."] = "bf6b174b1213cc9fc8478d3b5f2b4971",
		["The darkness does not embrace you, $c.  Cease your prattle and remove yourself from my sight!  Be gone!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "768f0928588ebe52253715a9f6b21ad7",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "cc24e4d0a2cf60bd7ee0678b7a460964"
	},
	["Alamar Grimm"] = {
		["The arcane only corrupts those who are weak. Keep up on your training, or you may find a similar fate."] = "073492d1b775dad17b73e4495accc8b7",
		["I'm afraid your darkness quotient isn't sufficient enough for me to bother talking to you any further.  Move along please."] = "8045db4a1a25656b86eb87b955fbe642",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "9a3480cee0a48d3503a6ac98b0adb1d6"
	},
	["Demisette Cloyce"] = {
		["The arcane only corrupts those who are weak. Keep up on your training, or you may find a similar fate."] = "c381816693d5bcf8cf6644c3ad7a0dea",
		["The darkness does not embrace you, $c.  Cease your prattle and remove yourself from my sight!  Be gone!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "768f0928588ebe52253715a9f6b21ad7",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "cc24e4d0a2cf60bd7ee0678b7a460964"
	},
	["Elaine Trias"] = {
		["Just browsing my wares or is there something specific I can help you find today?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?"] = "930e45368ed7dcac8e799df8fa5bc730"
	},
	["Quartermaster Lewis"] = {
		["I try to keep Sentinel Hill stocked, and that's not easy with all the action we see."] = "f25d9eb86b1a32dfb1649beab901ef4c"
	},
	["Smith Argus"] = {
		["I'm sorry, I'm a bit busy right now making horseshoes for Verner Osgood in Lakeshire. "] = "80c8a703f2783e988393cdc3f26954dd"
	},
	["Thor"] = {
		["Where are you going?  Well if you're looking to get there quickly, then look no further!"] = "a8c3fee28c1869e9b77707e11b8cd0a2"
	},
	["Nalesette Wildbringer"] = {
		["You've come for training in order to pass it on to your pets?"] = "89218c24a0eff1fa5c10022467769ef7",
		["Ah friend, I only help hunters and their pets."] = "4c9a93178a8bd81be46f856336284914",
		["Just like hunters, pets can choose specializations. Ferocious pets, like cats, can dish out damage but can't take it as well. Tenacious pets, like turtles, are more defensive and can occupy an enemy's attention while you stay at range. Cunning pets, like spiders, have a mix of offensive and defensive abilities and are particularly useful in Battlegrounds and Arenas.$b$bEach pet comes with a default specialization, but you can change it if you like."] = "bd6a3c681112b21859e2604b29965b54",
		["You can't teach an old dog new tricks.  At least that's what someone once told me.  Lucky for you, I've discovered it to be untrue.$b$bNow then, would you like your pet to unlearn talents?"] = "d672c02f577b108714ebbb44ef3fb6b3"
	},
	["Hemet Nesingwary Jr."] = {
		["My father's off to more exotic locations in search of bigger prey.  Don't worry though, we're still on the hunt here!"] = "75d66b38c9fb1c861b57d930fbe581cf",
		["Another fine day in the jungle!  It's going to be quite a hunt,  I can feel it.  Once Barnil is done cleaning the guns, I'm taking the hunting party deep into the twisting vines.  Not such a bad way for an old war vet to spend his retirement, eh?"] = "3b2fff9c8477038167bda5328b333dd3"
	},
	["Barnil Stonepot"] = {
		["Master Nesingwary has a big hunt ahead of him.  I find helping him prepare for a day in the jungle is much more relaxing than helping him ready for combat.  Although I do miss some of those glorious moments on the battlefield."] = "e3a348a35882a9d1e3d9c86ff56b6bbe"
	},
	["Ironforge Mountaineer"] = {
		["The Vault in Ironforge is the closest bank ye'll find in these parts."] = "0a458a8ce29f14328fcabdfd47465864",
		["The closest gryphon master is located up in Ironforge near The Great Forge itself.  Ye'll need to head to Ironforge if ye want to travel by gryphon."] = "6305fe6a707e427afab2f360b1207c14",
		["If ye need to get yer hands on some guild creation papers ye'll have to head up to Ironforge and visit the Ironforge Visitor's Center."] = "df16ab95e00ffb92b3fed9ef52d44b97",
		["Oooh, an Inn is it?  Well, ye just can't beat the Thunderbrew Distillery.  Rest if ye must, but be sure to have an ale or two while ye're there."] = "faccba89ef46051a5379645c564e3839",
		["Shelby Stoneflint houses a good deal of pets for the local hunters.  She can be found over by the Thunderbrew Distillery if ye need her to look after a pet."] = "0c655b7e4b51016d75c260e3814778a6",
		["If ye ask me, I think Grif spends a little too much time with the animals.  Still, nobody else knows the hunter's path quite like he does.  Look for him outside the smithy in Kharanos."] = "e065e6ffbd85c69cf4065d6e6b66f353",
		["Ye sure ye don't want to learn to be a warrior?  Well, it's yer hide on the battlefield.  If ye really want to learn to waggle yer finger, ye best talk to Magis Sparkmantle in the Thunderbrew Distillery."] = "7a06bc28fb12ba20a5675e5411b6fe9b",
		["Ye need some training?  Well, Azar Stronghammer is always up for showing the younger paladins a thing or two.  Why don't ye go see him in the Thunderbrew Distillery."] = "11995b9db35dcc041a69901ec848f69f",
		["Ye'll surely find Maxan Anvol tossin' back a few in the Thunderbrew Distillery.  Why don't ye go have yerself a pint and see if he'll teach ye something new."] = "715708ba36f18b5a3fbfb8686883db9e",
		["Ye looking for Hogral?  Well did ye check the tavern?  Och!  If yer looking for a rogue, and a dwarf one at that, ye should start in the Inn!  Go have a look already."] = "899fb8890366bc8523184f4390958a8a",
		["That kind of magic is just bad news, I tell ye.  I don't know why that Grimrizz has been allowed to set up outside the Thunderbrew Distillery of all places!  You stay away from him, you here!"] = "463502c56847ed7243d50dd9d7dfe996",
		["That Granis Swiftaxe could drink a fish under the table and yet his axe still swings true.  However, if yer looking for training, ye best catch him while ye can understand him."] = "b3eb25da18983fdf212771948dd2ead9",
		["I hear there's a shop up in Ironforge run by the gnomes that specializes in alchemy.  You should go have a look."] = "7001a21e963d74424808d69f17d668f5",
		["Ye can probably hear Tognus beating away on the anvil when yer in Kharanos.  Although, if ye haven't cleared the wax out of yer ears recently, then why don't ye just have a look in the smithy."] = "2e06426e30248977c8c20eb4332316c6",
		["Gremlock doesn't always have the best of luck with cooking, but he does have some tasty recipies worth learning.  Go chat him up in the Thunderbrew Distillery and see what he'll teach ye."] = "15ad84e66e4c58eea9cd9c0ed333b1f5",
		["Ye should take a look in Ironforge if ye have yer mind set on enchanting.  I think I saw a shop over by the gryphon master last time I was up there."] = "4109a0c5207a8b28fc00626b2e4222c3",
		["With all the screws that Bronk has been tightening, I think he's let a few of his own go if ye get me.  All the same he's still got a good head for engineering the darndest devices.  Ye should go pay him a visit over at Steelgrill's Depot."] = "ba9d6c2edc06e3ac18095540f49eded4",
		["Good ol' Thamner bandaged me up just the other day when I had a run in with a nasty trogg.  I'm good as new I tell ye!  I'm sure Thamner would be happy to show ye how to make a good bandage."] = "d31bc075c7dd96f30d85a96af073b884",
		["Only a few spots to get any fishing done around here.  Paxton knows them all and probably a few he won't tell ya about.  Why don't ye go over to Iceflow Lake and see what he will tell ya."] = "bfa3e99f5447c0613e58f162697277c8",
		["Nope, nobody who can teach ye herbalism out here.  I think ye'll have better luck in Ironforge though."] = "cab6e4ab27cf26be06df311db8ddc605",
		["Ironforge is going to be your best bet for leatherworkers.  If memory serves, there's a shop by The Great Forge that should meet yer needs."] = "8c47c63bae131cfc4c703e5e64928b9d",
		["A miner?  Ye don't need to ask if $glad : lass;, only where!  Yarr is who yer looking for, and I think ye can find him hiding out over in Steelgrill's Depot."] = "51e9e220aa1363fc4467d6474936feec",
		["The skinners usually take all their hides into Ironforge to dry out.  Why don't you head there and see if you can find one to train ye?"] = "ec0c07dcf4ff205521d2f5d0a1068949",
		["Well, ye won't have much luck with finding a tailor out here.  Ironforge is home to a quite a few talented tailors though.  Why don't ye go ask a guard there."] = "4b0a2e9278f03926eef7d0759b777510",
		["What do ye need directions to?"] = "d388655d9228134e7b31d1853f043c46",
		["The nearest bank ye'll find is The Vault in Ironforge, $glad : lass;. "] = "08c9ceafdad651bbbebbd3cb6b0da276",
		["Ye won't find a gryphon master just anywhere around Dun Morogh, $glad : lass;.  Ye're going to have to go to Ironforge if ye want to take a gryphon somewhere."] = "d0c05565ac77b541571d995b15b938ac",
		["All those official types reside in Ironforge.  Ye'll be wanting to check out the Ironforge Visitor's Center for guild creation papers."] = "22cf5f4470c34fdfceb62617022d8818",
		["The Thunderbrews run a fine Inn in Kharanos which bears their name.  Stop in for a pint and a bit of rest."] = "aab9b5fec69dbc10d53c8cad83e75885",
		["Well $glad : lass;, ye can find Shelby Stoneflint right outside the Thunderbrew Distillery in Kharanos.  She'll take good care of any pets ye might have."] = "1a2d71850eb88001be897a78dd054b56",
		["Which class trainer might ye be looking for?"] = "9b595586ad3950bc13ea91b62909e02a",
		["Which profession trainer would ye be looking for?"] = "d749a37c4ce4aff92ff3d1043c365314",
		["There's only one hunter around here I would have ye talk to, and that would be Grif Wildheart.  Ye'll find him standing just outside the smithy in Kharanos."] = "5c5fe1d86ad4b031fa84cfd353313a03",
		["There's a mage at the Thunderbrew Distillery who might be able to teach you some new spells.  I believe his name is Magis Sparkmantle."] = "e1b53b46c35628bcdedb2790d26f015f",
		["Och... a paladin?  Well $glad : lass;, ye're in luck!  Azar Stronghammer is back from training and is currently staying at the Thunderbrew Distillery in Kharanos."] = "033b8bdb60295b45c231207cd9543a0c",
		["Oh, a priest is it?  Well good ol' Maxan is sure to be found having a drink in the Thunderbrew Distillery if ye need a bit of training."] = "fdf9faecf793a21b32e39022a05eb4c8",
		["Well then, it seems we're both looking for Hogral Bakkan.  He's a dwarf to be sure, so sooner or later he'll be heading for the Thunderbrew Distillery for an ale -- he might even be there now."] = "e68bada53f5fa97995506dff73ad5ed0",
		["Warlocks... I don't care for their lot.  Like that Grimrizz who's set up shop outside the Thunderbrew Distillery. The ale will probably go flat there because of him!  Warlocks... bah!"] = "92d4459148dbbf362eaa5bb606cfca2b",
		["Och!  Now ye're talkin'!  I bet Granis Swiftaxe could show ye a thing or two about swinging steel.  He's over in the Thunderbrew Distillery in Kharanos at the moment."] = "edb27f0d96c3518284636aa70e0e5090",
		["Nope, no alchemists out here in Dun Morogh.  Ye best take a look in Ironforge for them... try the gnomes in Tinker Town."] = "2a3641e85aeb84f1ade37c52f41f4389",
		["Och!  Now that's a skill worth knowing.  Tognus beats the anvil with a fury ye don't see often.  Why don't ye go talk him up and see what he can teach ye?"] = "d4027d81c3fda31335fb60590d1580ff",
		["A Thunderbrew ale and a bit of Gremlock's cooking makes for a nice meal indeed.  Ye really should hit him up for some training if ye want to be a cook."] = "041936041e8c95901a54a5af104934a9",
		["There aren't any enchanters out here in Dun Morogh that I know of.  Ye're going to have to visit Ironforge if ye want to learn the enchanter's profession."] = "02c74a6a6a8473c04a7871ada5ef68ef",
		["Ye should check over at Steelgrill's Depot for Bronk.  When he's not tinkering with some odd device, he's usually chatting up the pilots about their steam tanks."] = "6827d7fa9354fe5b3d5ee5e4ec994c05",
		["First Aid may not make up for a priest's healing, but it's handy in a pinch.  I recommend ye go talk to Thamner in the Thunderbrew Distillery and learn what ye can."] = "97ef7fee53ac4b1676b6521925e5daa4",
		["Not much fishing to be had around here, but what little there is to be had is Paxton's ye can be sure.  Ye can find him fishing out on Iceflow Lake."] = "63b417fb72c82246bb2fb6d436430390",
		["Amazing to see little flowers persist in the cold of Dun Morogh...  but ye won't find any herbalists out here.  Ye'll have to go to Ironforge to get some training in that profession."] = "fb81348f1025aa16ca00e034981a4072",
		["Elise Brightletter is near the Great Forge adjacent to the Flight Master."] = "d23e8db6b16d018afcc2298e7459ce5e",
		["If ye're looking to learn the profession of leatherworking, ye're gonna need to travel to Ironforge.  I hear there's a nice shop near the Great Forge where ye can learn the profession."] = "a22f46b9e130e7ea7bbc0cdcb720369d",
		["Surely ye didn't think ye would find a town without a resident miner about, did ye?  Yarr can usually be found over at Steelgrill's Depot just outside of Kharanos."] = "ee1de3a15b90702726734a7d600b5af6",
		["Ye won't find any skinners out in here Dun Morogh $glad : lass;, they're mostly to be found in Ironforge if ye're looking to be trained."] = "092466019a99f26ac94b02b85f65c7f1",
		["Ah, Stonebrow doesn't leave Ironforge much these days so if ye're looking to learn the tailor's profession ye'll have to go to see him up in Ironforge."] = "575ae34b59f3449de7632556741f13ea"
	},
	["Private Thorsen"] = {
		["This is a dangerous place, $n. Be careful around here."] = "a765bd81d4444d7fa3d03cdef9f00bd6"
	},
	["Grelin Whitebeard"] = {
		["The trolls are acting strangely, $n.  I don't like it.  I don't like it one bit."] = "2a361dfc2fa84e1363588bcf8b47c116",
		["Greetings, $g lad : girl;. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..."] = "df26604e6baae8d611472c0496eb53e6"
	},
	["Alma Jainrose"] = {
		["I can instruct you in herbalism.  Interested?"] = "8fb90ad7d34714ad858fa4016e339e62"
	},
	["Durnan Furcutter"] = {
		["I sell the finest cloth and leather garb this side of the valley!"] = "0f7736dc9f16d7152dca3f99e5a42807"
	},
	["Branstock Khalder"] = {
		["The Light protect you, $c."] = "852369f0d2fbc11e555e75fe5a433853",
		["I hope the Light is with you, $n. Is there anything I can do for you today?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
		["Elune be with you, $c."] = "bc51c6ac6dd1cdbedae9b46a77a4424f",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "31ab172e1a375db1c9157d594eb608d9",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "80cc43994e8ec2dbd1e429d9f2d36fbf"
	},
	["Donal Osgood"] = {
		["I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin."] = "a88973a558029a639cb379b7365f229a"
	},
	["Thorgas Grimson"] = {
		["Wot kin I do fer ye?"] = "ff4c1db50d39977890db3fe889ea21ae",
		["I kinnae help ye with trainin'. Ye should look fer a $c trainer."] = "65ffa984c80ec793cab656acd848ac8c",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "31ab172e1a375db1c9157d594eb608d9",
