	["Eldrin"] = {
		["I can tell that your wardrobe is in dire need of care."] = "b34aad75e8e14753d5e47ece1a2eba61"
	},
	["Marek Ironheart"] = {
		["Here at the Farstrider lodge, we prize hunting skills above all else. Wish to gain my approval? You'll have to earn it.$B$BYou look up to the challenge, $Glad:lass;!"] = "b9a009c23ae18be4d2beb4d5b487dd08",
		["You've become quite the hunter, $n! Not only have you proven your skills, you also bested Daryl, which gets you extra points in my book!$B$BYou're welcome here any time."] = "f5c3b81ff7aa2cea4c40a37dadb0f053"
	},
	["Vyrin Swiftwind"] = {
		["Get that head and it's sure to give Daryl a fright. Not that he doesn't deserve it, the bloody arrogant fool. But ha! I can't wait to see the look on his face when you show it to him."] = "9e6b0659e0e966c06c69f9a837f1aff8",
		["Welcome to the Farstrider Lodge, $n!"] = "20130ee4095bd8f7b2294799f450bad7",
		["You're always welcome here, $n. Thanks for the laugh -- and don't worry about Daryl, he had one coming!"] = "96fa99fa82173bfadc8ff6676599cba7"
	},
	["Alchemist Mallory"] = {
		["Good day, $gsir:ma'am;. I'd shake your hand, but as you see, I'm in the middle of something. May I be of assistance?"] = "fc05789524675185326e36bb917847b7",
		["You've made a good start, but you still have a great deal to learn, $n."] = "8d1a9653ec0ac81cbb827f31a1138bda"
