	},
	["Julia Gallina"] = {
		["Just browsing my wares or is there something specific I can help you find today?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?"] = "930e45368ed7dcac8e799df8fa5bc730"
	},
	["Bernard Gump"] = {
		["We are the only supplier of healthy flowers in all of Stormwind. We provide beautiful blooms for any occasion."] = "8235974cfa833adfdaf9b2864225d19f"
	},
	["Felicia Gump"] = {
		["We are the only supplier of healthy flowers in all of Stormwind. We provide beautiful blooms for any occasion."] = "529a618c35100390b17d2f2740d430aa"
	},
	["Darian Singh"] = {
		["I sell only the finest arcane gear, made by the crafters and mages here in the city of Stormwind."] = "2e4eca05cb76135045a9a7c0e66e45af",
		["Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise."] = "52ce57327118edf04bd3864c3342a693"
	},
	["Jarel Moor"] = {
