	["Mathrengyl Bearwalker"] = {
		["What brings you to the Cenarion Circle, $n?"] = "fb107f4dbefdbafaf3a91b5c9b3d998b",
		["Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, as Cenarius has taught us.  Never forget this."] = "bc1493e1b606e5c0788ef13ee5b1227a",
