	["Nissa Firestone"] = {
		["The esteemed Doctor Gustaf VanHowzen can train you further.  He can be found in Theramore treating the wounded at the barracks."] = "199504472bb3974f17f406ea4b61db6d"
	},
	["Jormund Stonebrow"] = {
		["Ah, this Darnassian fabric is the finest!"] = "5eab0d76d4ff9ea837e56c38ac2add13"
	},
	["Gimble Thistlefuzz"] = {
		["Who are you? What do you want from me?"] = "8632fa71e51a2117b8aea60d681a69cd"
	},
	["Daryl Riknussun"] = {
		["I keep 'em fed, kid. Yep, Daryl Riknussun, at yer service."] = "039eb14670494f86ef32cacf9598a8de",
		["Seek out Shandrina in Silverwind Refuge.  She can sell you the 'Expert Cookbook'."] = "fe8baba790f8edd0a4e3d2f680dfe89a",
		["Dirge Quikcleave of Gadgetzan is a master of the culinary arts.  To better yourself you will need to seek him out."] = "de96efe8437890d30d0aff9e01f5f7cb"
	},
	["Grimnur Stonebrand"] = {
		["You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently."] = "b4e4101905820aead3b6b58b95cdc8ed"
	},
	["Grumnus Steelshaper"] = {
		["Ye bothered me for that? Ye'd be better off strapping a dead rabbit to yer back and running through a Troll's den than wearing that piece of garbage."] = "199016ae1623083a335a02df66eb48dd",
		["Welcome back to the Great Forge, $n. Ye come to visit an old Dwarf or do ye think yer ready for the next step in yer training?"] = "a07c9ac1b4c67fa1992198a90d99379a"
	},
	["Hulfdan Blackbeard"] = {
		["He grows fatter and more corrupt with each passing day. Ye can smell the stink comin' off o' his body. He be dirty, an' I dun just mean he be needin' a wash.$B$BEnough babblin' from Hulfdan. Where did ye come from and how can me help ye, $c?"] = "9c2605135c90fe4ebb2f1462c17f512d",
		["Can't help ya, $n. I only train rogues."] = "fa078d44ecb0731e4c2a45f949ae67b1",
		["Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?"] = "31ab172e1a375db1c9157d594eb608d9",
		["Dual Specialization allows you to keep two active Class Specialization, Talent, and Glyph sets and easily switch between them. You also will have separate glyph panes and action bars for each set. Switching between the two sets cannot be done while in combat and will consume your available resources."] = "80cc43994e8ec2dbd1e429d9f2d36fbf"
	},
