	},
	["Thrumn"] = {
		["Looking for a tabard?"] = "c4a6ab04be44e1d5de762f4b04b19f5d"
	},
	["Merill Pleasance"] = {
		["Looking for a tabard?"] = "98df31082a5ae18385bea81382d7ddd2"
	},
	["Shalumon"] = {
		["Looking for a tabard?"] = "677f89521e5243d6c944eeb381ec49ac"
