	},
	["Stephen Ryback"] = {
		["I don't get too many cooks in here looking for training, but I guess I could teach you something if you're ready."] = "3c4abd8c1180a4b2995e00e2dd2cede0"
	},
	["Erika Tate"] = {
		["I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin."] = "1d035ef80655c9d2cd4e435e275a7bba"
	},
