	["Arnold Leland"] = {
		["Welcome to Stormwind. Took a long time to rebuild her but it was well worth it. So are you visiting, or are you here on business?"] = "e980a3fd7dce3ba0d906cea472aaa320"
	},
	["Catherine Leland"] = {
