	["Guchie Jinglepocket"] = {
		["Greetings, $n."] = "ca7d5d5e8f3765b7ce9e7f06746c5f05"
	},
	["Wing Commander Ichman"] = {
		["I was shot down by that reckless fool, Mulverick. I fear that if I do not make it back to base, all will be lost! Mulverick and his squad of War Riders must be stopped!"] = "13bd8ec571cbe1068c2b561f43c20626"
	},
	["Wing Commander Vipore"] = {
		["I can't believe it... I was doing a routine recon mission over the central DMZ when all hell broke loose. I saw the Horde Wing Commander, Mulverick, take out both Ichman and Slidore! Anger took hold of me and I broke from my wing man and drove that show-off, Mulverick, down. Unfortunately, he clipped my gryphon before he crashed, forcing me down as well. I ended up captured by these savages.$B$BI have to get back to base! Help!"] = "5eff59a8c2052a48242dfc3d389971a7"
	},
	["Arch Druid Renferal"] = {
		["My faith guides my actions, $r. I know that Ivus will come."] = "989b8cf07c5b1f4c2647593ee2dbb60a"
	},
	["Druid of the Grove"] = {
		["It is not for us to judge these atrocities. Ivus will pass judgement once he arrives."] = "42dd34a51960b347c69dae54ee708aac",
		["The Arch Druid believes that Ivus the Forest Lord will come once he is made aware of the destructive forces within this valley."] = "7c830036d8293d0280f91824933be0d1",
		["We have been sent here from Darnassus to aid the Stormpike in their time of need."] = "ef448e3b4ee14cfbe64e1c64306cc44a"
	},
	["Greatfather Winter"] = {
		["Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter Veil.$B$BHo ho hurry up."] = "69b32b5508e2336146c63141a8a20692",
		["No... you can't sit on my lap."] = "d182853c15566b0e4b66ef86169f2b6a",
		["I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it."] = "56e883add54dbdeee15af3096f46347a",
		["A wondrous Winter Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum."] = "7b7ab2524c993341ccbbe645e060df14"
	},
	["Great-father Winter"] = {
		["Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter Veil.$B$BHo ho hurry up."] = "9b082716652d0a01d9cb9904fdcba584",
		["No... you can't sit on my lap."] = "66f90f5438555127b635f6c18ceba9ca",
		["I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it."] = "0a5fc9eb27704fbbe32ca289b8ccbc8c",
		["A wondrous Winter Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum."] = "0bb5841841b3d5a0f7d353e047e585b8"
	},
	["Corporal Noreg Stormpike"] = {
		["$n, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available."] = "be7b74ece350a6df351c868dce888f81"
	},
	["Stormpike Ram Rider Commander"] = {
		["Death to Frostwolf!"] = "29c1705d91a331e6239a596f074aa9f1"
	},
	["Frostwolf Stable Master"] = {
		["Greetings, $c. I can help stable your pets or assist you in recovering lost companions."] = "d8bcd237e1216ba773f65e8398f55bdc",
		["Greetings, $c. I can assist you in recovering lost companions."] = "94425343a80d214efb3536a4f39f02f6"
	},
	["Stormpike Stable Master"] = {
		["The indigenous rams of Alterac are vital to the functionality of our cavalry!"] = "089e884fad1004ecb78852e5b6c1ed36"
	},
	["Cavindra"] = {
		["This place... it's cursed.$B$BI barely managed to escape, and I cannot bear to go down through the tunnels again.$B$BMy brother, and sisters though... They were not as fortunate. Trapped inside, they are feverish with the corrupted haze that flows from the evil garden growing there.$B$BPlease, you must help."] = "6adc96ab36eaaf0a90d7a9e8723325a3"
	},
	["Keeper Marandis"] = {
		["May Cenarius guide you, $c.$B$BI am here in this corrupt land with my sisters on a mission of great importance to the Cenarion Circle. But only those who are powerful enough I ask speak to me about such matters--to send a lesser being would be folly."] = "b8afcde25b0b0980f04983990b8c5206"
	},
	["Selendra"] = {
		["My sisters and I have come down from the Stonetalon Mountains to put to rest a tragedy from ages past. Unfortunately, we are not powerful enough to accomplish our goals on our own and now seek mortals such as yourself to aid us.$B$BIf you are powerful enough, then we have much to discuss, $c. If you are not, then, for your safety, I will leave the details of my mission out of our conversation."] = "779a7062b06c43fd9213c4565eb756c6"
	},
	["Celebras the Redeemed"] = {
		["At last, I am free of the corruption that once bound me to this place..."] = "d47befd77160caee1bd4258917181801",
		["Long ago, my dryad sisters and I entered these caves to free the tortured spirit of my uncle, Zaetar. However, the corruption that had already spread through these caverns soon overcame us, and we too fell.$B$BWe were destined to wander these passages; the toxins poisoning our minds...$B$BAlthough my spirit may now be at rest, I know that I have failed in my mission. It is a great sadness I must bear..."] = "7de446ebddf45b56cbf7eaee14c70f1d",
		["Ah, Zaetar... <Celebras looks away.>$B$BMy father, Remulos, tried to stop him...$B$BZaetar was headstrong, and when he fell for an earthen elemental princess, my father knew that their union was cursed, but Zaetar refused to listen.$B$BThe centaur are the result of his mistake. They were born misshapen and hateful; my uncle Zaetar was killed by his own kin...$B$BThe evil princess, Theradras, still guards his remains here in the crystal caverns."] = "5810e90feeda6f30ea95fe35dd358f75",
		["You ask of the Sons of Cenarius, Remulos and Zaetar.$B$BMy father, Remulos, was strong and beautiful, and my uncle, Zaetar, very cunning and slight of build. While they were respected quite equally, Zaetar always felt as if he could never quite compare to the glory and attention he thought Remulos had.$B$BAfter my sisters and I were born, Zaetar, blinded by jealousy, set out to outdo his brother... He was the creator of his own end. The sadness it brings me has never lessened, even as time passes..."] = "d28d4e81ca17c6dde4cc347bde52c983"
	},
	["Centaur Pariah"] = {
		["I need no home to know I still have a place in this world, $c. The tribes will see... all of them. They fight amongst one another, and for what? Scraps left over by vultures... lands infested by the Legion... bah!$B$BThe centaur should be proud of their heritage--it is just as noble as any Night elf's or orc's--it is time we started acting like it!"] = "958b734e41c4c3450d9971232c7ef98f"
	},
	["Corporal Teeka Bloodsnarl"] = {
		["Come to learn, eh? Well I just might have some work for you, scrub."] = "832d7cd84aaed062179a1a03bf687405"
	},
	["Sergeant Durgen Stormpike"] = {
		["<Sergeant Stormpike salutes.>$B$BName, rank, and serial number, soldier! That's the only bit of information you'll ever give those dirty Frostwolf dogs!"] = "91ec0e39bf7d8d69df78d4e9d0d5607c"
	},
	["Warmaster Laggrond"] = {
		["I am in charge of recruitment for the Frostwolf Clan. As a soldier of Frostwolf, it is your responsibility to check in with me as your rank among the clan rises.$B$BHonor and respect are earned on this frigid field."] = "ce047d2a3dd6d9e301b393ee2954c796"
	},
	["Lieutenant Haggerdin"] = {
		["Hail, $r! I am Lieutenant Haggerdin, officer in charge of recruitment for the Stormpike Guard.$B$BAs you gain prestige and notoriety among the Stormpike, return to me and I shall see about upgrading your insignia. Also, should you ever lose your insignia, I am able to supply a replacement."] = "3df9d5b384b97d45f30cd9ba4c8d25a8"
	},
	["Ironbark the Redeemed"] = {
		["Thank you, mortal. There is but one service that I may offer to you before I return to the Dream.$B$BThe door to Zevrim's master, Alzzin, blocks your path. I shall act as your instrument of destruction. The door will be opened, I merely await your command."] = "527ec81579e3144226a578a5bdd1a9a3"
	},
	["Human Orphan"] = {
		["If you try to fail and succeed, what did you just do?"] = "00d3e1c7940ca76f3315cd0138dbfad8",
		["Do fish ever get thirsty?"] = "2e14a994220d5ab66a84d2b12c9a0907",
		["What happens if your snot freezes in your nose?"] = "f36c2338b475dceaf4421d070d8b1fdf",
		["If overalls are held up by the snaps at the top, then why do they have belt loops?"] = "be279a69b78cc18cb55449a51b3bbc95",
		["Mushrooms always grow in damp places and so they look like umbrellas."] = "9bfd76d5461fdf7a7163d27826e753d4",
		["I've been to Ironforge before.  It smells funny there."] = "47686532f39e11ae621b3d9c28f74bd5",
		["When I grow up, I wanna be the king of Stormwind!"] = "43ed348119d3a4c29aff440804ce9635",
		["Did you just come out of a dungeon?  Did you get me anything?"] = "907ba3b70186c2ef4363c95c862055b1"
	},
	["Guard Fengus"] = {
		["You da man now, dog!"] = "f951e7cd65d443f5753c3c23dd8d91a3",
		["Fengus make you fierce!  Crazed!  RAR!"] = "2e87c5405a00a15ac8972b6b343d611d"
	},
	["Stomper Kreeg"] = {
		["You da boss now, yeah?  Long live da new king!$B$BKreeg let you look at Gordok hooch.  Ogre hooch best of all hooch, and Gordok hooch best of all ogre hooch!  Maybe you buy some from me, ya boss?!"] = "a5b8785f700475a6cbb2223a642aecc4"
	},
	["Guard Slip'kik"] = {
		["You got me good boss!  How you get by Slip'kik??  I smart though, I watch next time!  Har har!$B$BNobody get by Slip'kik no more. Slip'kik promise!"] = "2a7f0c524712f48206d6c87fc756a7f5",
		["I show you how smart I am, boss!  You be extra smart with mighty magic mojo now!$B$BUm... maybe Slip'kik use magic on self. Dat would be good idea..."] = "10a4f813915f8096eec34d7f2cd6af8d"
	},
	["Cho'Rush the Observer"] = {
		["Uh... I sorry I attack you boss.  You no kill me, please OK!?  You da king now, and I help make your tribute better!"] = "4caad15f7dffcede372017717f618670",
		["If you not talk to Mizzle, you not become da king!  Talk to Mizzle da Crafty!"] = "855d4bae199712a60cbca7d53d75de17"
	},
	["Captain Kromcrush"] = {
		["What you doin' wanderin' around here?  Why them small fries not in da shackles?!"] = "cdc76bc40a9ce2e36e65e7d1f897ed6a",
		["You da strong one now!  All hail to da new king of da Gordok!"] = "1643278c6274d6479354539359dce2ae",
		["Do I see them with weapons still?  Why you let them keep their weapons?!"] = "4774049e54e5b253c5a9e0ac88e13e11"
	},
	["Guard Mol'dar"] = {
		["You are da king of the Gordok!  You're A-number-one!"] = "49c68a763b64c356f1d289eb2b3464ce",
		["I heard you was dead... well, you won't be easy to make dead after this!"] = "12d7e225e6201009cea2f2a9228d1c57"
	},
	["Knot Thimblejack"] = {
		["See that broken trap over yonder?  The ogres are too stupid to figure out how to fix it.  Clearly, it needs a little tinkering!  If you fix it, I bet you could lure Slip'kik into it, and BLAMMO - trapped ogre guard!"] = "b2071a5aeae89cc1c64e894d737e43d5",
		["You found a key?  Well, is it THE key?  I mean, is it the key to unlock these shackles?  Well $G sir : ma'am;, there is only one way to find out!"] = "f16f9a2346eaf3e9c5845add6a7d7cc3",
		["Well, from what I've gathered while waiting to be eaten by these yokels... it might not be necessary to kill every ogre you find here.$B$BThe ogres were going on and on the other day about how King Gordok came to power; specifically, he killed the previous king and took his place.  Well, the king's henchmen - those that Gordok spared - immediately swore fealty to the new king.$B$BWho knows - the ogre you save could very well be your own... figuratively speaking, of course!"] = "44eabdbf357ad63028027e138439ffaa"
	},
	["Highlord Demitrian"] = {
		["Look to this ravaged field and know the power that the elements hold, $r."] = "c249a2eaed40f813e602ee17f9452029",
		["I know much, listen and be educated, $r."] = "7624b1b9032ec89ab17724443dfdadf7",
		["In the time before time, what the usurpers would later call the First Age of Creation, my master and his siblings ruled over this world. It was they, the Old Gods, who created all.$B$BAnd it was they who would ultimately be cast down by those that would call themselves Shapers. "] = "c09678227a9af6c89356887b10213442",
		["Their manifest forms weak from eons of battle, imprisoned beneath the world - the world that they themselves created - the corruption of the Titan Shapers would permeate through the surface and befoul the Old Gods.$B$BIt was then and there that the brothers did turn. For five millennia a battle was fought at the core of this world. "] = "c3df5cd0dcec466f8c0f5df4b18f5778",
		["It was during the Elemental Sundering that the Firelord, Ragnaros, would seek to consume my Lord, Thunderaan, Prince of Air.$B$B<Demitrian bows his head, his face contorted in rage.>$B$BSpeak his name and I shall decorate this ravaged camp with your entrails. Be silent and listen. "] = "3c68b84890ff85616d98587fcb79722c",
		["It was the Lieutenants of Ragnaros, Geddon and Garr, who would perpetrate the betrayal against my Lord. Thunderaan was caught unaware."] = "95a34dbc84fe0dbe175240f3ab72667f",
		["The Firelord's advances were wholly unknown to Thunderaan. Before my Lord could react, Sulfuras, legendary hammer of Ragnaros, would strike an unmerciful blow. Thunderaan fell, utterly defeated.$B$BThe Firelord feasted upon the essence of my Lord, but was unable to consume him entirely."] = "e102fa0f9aa47c2f42746046e41a2b68",
		["What little remained of Thunderaan's essence was stored within a talisman of elemental binding. Ragnaros then shattered the talisman in two flawless pieces. The pieces assigned to his Lieutenants... "] = "7c45d7a2e7d8583c1a973293c5feecd4",
		["<Demitrian falls to his knees.>$B$BYou have recovered my Master's eternal prison!$B$BOh long have I waited for this day and finally, it is realized.$B$BHe must be released!"] = "c7d0d5f0497c7bbd94f17ecb262de67c",
		["I hold the vessel of his rebirth. Should you be prepared to take on this task, you will be required to fortify the vessel and ultimately, break the hold of Ragnaros himself!"] = "0ba174f63cc2f24d23e0cfd845eb7767",
		["The vessel of rebirth must be fortified with elementium. I know of only one source of the mineral: the elemental planes, at the core of our world.$B$BThere is one, an Earthshaper, who may know more than I about the acquisition of such things. You must find this Earthshaper!"] = "df4e9cd871fca0c53d2e4b158280e34f",
		["The corporeal form of Ragnaros must be destroyed. From the remnants, his essence shall emerge. In this weakened state, Ragnaros' grip on the prison of Thunderaan is loosed. The essence itself acting as a key..."] = "367f05e456b6a76006091647e119a824"
	},
	["Earthcaller Franzahl"] = {
		["I study the known and unknown elements of our world."] = "221f2bd28a2fe636ecc07941a4ae6f72",
		["Elementium? I have not heard that word uttered from the mouth of a mortal in decades."] = "55ed0468e4c525bb70ab8dd0d3a7676e",
		["A former student of mine by the name of Krixix spent a lifetime attempting to make contact with the chained Gods of the underworld. He pursued that which would spring up from the ravaged earth... That which would form only as a result of the elements clashing in titanic conflict.$B$BElementium as it would be known to mortals.$B$BOne day, nearly a decade ago, Krixix's pursuit lead to a fissure forming in this very gorge."] = "5c80f03f00a13e4c498a065a501fad0c",
		["Aye, he had done what was thought to be impossible. Out from the fissure sprung an agent of Therazane!$B$BFrom my vantage point, I could see the goblin holding conversation with the agent of the Old God. What happened after that was terrible..."] = "33c685b48274884313a16773d611311a",
		["The fissure closed and Krixix was gone! Swallowed whole!$B$BBe warned, $r, what you wish for could very well become that which you do not want. You play with beings and arcana that are older than time itself!$B$BShould Krixix be alive and should he have the information which you seek, you can be certain that he will not give up said information. He has faced terrors far worse than you could ever dream to perpetrate."] = "672dd6bb8ec4811dd444af67fd330dd7"
	},
	["Mizzle the Crafty"] = {
		["You big boss now!  You king!  All hail King $n, King of Gordok!$B$BNow that you da boss, all henchmen will give you tribute!  You left some alive, yeah boss?"] = "cf8ead9541fa60fff2b543876438cbe3",
		["OK boss, when you ready for da tribue from your henchmen, you let me know!"] = "861f1358805c47287faa683299bf8435",
		["Um, you kill king, yeah?  That means you take his place.  That make you da new boss!  Hail to da king!"] = "2d926a415417de06f3d49ea2807f6359",
		["All henchmen of da boss - Stomper Kreeg, all three of da Guards, Captain Kromcrush, and da Observer - give tribute to da new boss.  If you kill a henchman, then that henchman can't give tribute!  Each one you keep alive will give you more tribute.  Keep all of them alive and you get da BIG tribute!$B$BYeah!"] = "4cf1eea2d2b534b5214fe8a946abf682"
	},
	["Pusillin"] = {
		["I hold the key to lands of free! Chase me and you'll see!"] = "085a9df99e28cd5e8a25b898701a42dc"
	},
	["Shen'dralar Ancient"] = {
		["Leave this place, stranger, lest it consume you as it has all that it has touched."] = "7c332deda31bef9904009677b9d72a0d",
		["Do you know of the Highborne? The Shen'dralar?"] = "a2c774e84977d54bfaa18464053d8daa",
		["The Shen'dralar were Queen Azshara's most revered arcanists. It was within these very walls that the Queen's most important demands were processed - often in secret.$B$BAfter the destruction of the Well and the subsequent lethargy that overcame the Highborne and lesser night elf sects, the Prince of Eldre'Thalas, Tortheldrin, began construction of the pylons that you see littering the halls of the west wing. "] = "6f0489b12a5ec110544130f0413137f8",
		["The Prince plotted to imprison a demon of immense power behind a grand force field. The pylons would channel latent energies into the field, keeping it operational.$B$BWhile imprisoned, Immol'thar would serve as a battery to the populace of Eldre'Thalas."] = "e087723e4de9c3a7afc0a6f3ff26dd25",
		["The siphoned energies would sustain the Highborne's magic, allowing those within the walls of Eldre'Thalas to feed their endless and growing magical pangs.$B$BThousands of years passed and the power required to keep Immol'thar imprisoned while sustaining life within Eldre'Thalas, began to shift. The cost to keep Immol'thar bound grew to overshadow the rate at which energy could be siphoned and distributed. The once net gain turned to loss."] = "deb78aef7ba1da9f9ee7748755557359",
		["The Highborne ghosts that you see wandering through the courtyard and halls of Eldre'Thalas were slain, not by invading Gordok ogres or satyrs, but by the Prince himself!"] = "cfd3885a86b7bc793e61d415369d4a5b",
		["The people were destroyed in order to preserve the Prince's immortal life and near limitless powers. The power once divided among thousands now funnels into the Prince and the Shen'dralar zealots. Those few remaining survivors are directly feeding power into the pylons in order to keep Immol'thar imprisoned.$B$BShould the demon break free of its bonds, it would surely destroy what little is left of this once great bastion of arcana."] = "6aef1308be672c7e59f0132f5147cc61"
	},
	["Lorekeeper Lydros"] = {
		["What you must understand is that being able to index 10,000 years of existence has given me a rather unique perspective on life. Your present day trials and tribulations are meaningless."] = "6c366d266feb0eb999723d20a1d0371f"
	},
	["Shen'dralar Zealot"] = {
		["The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince's lips. The Ashbringer could be found!"] = "4cfdfad3205a330e70b7b7c738d5bd7b",
		["I suspect that the imps are stealing knowledge."] = "9421d65ef798d5492d6265a1a2a8a487",
		["Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him."] = "02e172a647fe2f5421bb5b53d996e477",
		["Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre'Thalas."] = "319517c1f7485c844d80df08c6712507",
		["The Lorekeeper is an ancient. He has served under our glorious Queen!"] = "23317d5183b66048f0d84956c75f715a",
		["Many have come to this sanctuary, few have left. "] = "ac79c72eddc7e8fc12984358032b6d96",
		["Keep your voice down, stranger. You do not want to disrupt the Master's meditations."] = "9906d42902f11ddb1cdf6d7cf9d4b2c3",
		["We mustn't anger the Master. His is a wrath that is cruel beyond measure."] = "cb1ef7413e2015c25d838f4ca89cba30"
	},
	["Scholar Runethorn"] = {
		["Oh the horror! The tragedy! We are on the verge of a breakthrough, yet all could be lost."] = "5fc4f209b2ef0137dc307256ecdd2a18"
	},
	["Lorekeeper Javon"] = {
		["10,000 years of recorded knowledge tends to draw the wrong element to the Athenaeum. Books are stolen, recovered and stolen again on a daily basis."] = "cb6c6ca44638e05ae54e29542e26f374"
	},
	["Lorekeeper Mykos"] = {
		["Kildrath tends to overdramatize the situation. For example, 'Garona: A Study on Stealth and Treachery,' has been stolen over 400 times.$B$BThe mark of the Athenaeum protects the tomes, preventing any unauthorized viewings."] = "805f962da2b80257710186ac78724c01"
	},
	["Lorekeeper Kildrath"] = {
		["They've been stolen, $r! Three of our most prized volumes. Should you return the tomes, a reward will most certainly be yours."] = "e5bc2020af21f8dc760efcc4b9b1641e"
	},
	["Lothos Riftwaker"] = {
		["The fabric of which our world is woven is most delicate. It merely takes some knowledge and the application of said knowledge to tear the fabric. It is thusly that rifts are born. "] = "b31018acd6dd56a681e6c8a148317ac6"
	},
	["Overlord Runthak"] = {
		["I am he that carries out the Warchief's commands without question. I am Horde."] = "9f1fc0f188303aa506b43d5e4203e697",
		["Look to this fallen dragon, $r. The might of the Horde is unquestionable!"] = "5d36ebec7ba87ea72d8bc75fa1708950"
	},
	["Major Mattingly"] = {
		["I live only to serve our King."] = "9256c8087a9343192abe0385ab00858c"
	},
	["Griniblix the Spectator"] = {
		["Woohoo! They are into it now!"] = "e23b708f20364cfafc3bcefd5a823f72"
	},
	["Gorzeeki Wildeyes"] = {
		["Do you have any spiders or beetles, $c?  They scurry fast, but if you're faster then you'll find them quite a treat!"] = "767f180e80a535e7f390f3d311039337"
	},
	["Orphan Matron Nightingale"] = {
		["There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Alliance takes time to give something back to these innocents.  This time is called Children's Week. "] = "9452bcf77b2d46636d57c6303688913f"
	},
	["Orphan Matron Battlewail"] = {
		["There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Horde takes time to give something back to these innocents.  This time is called Children's Week. "] = "a004a2e73880cb6882c600c406454b14"
	},
	["Daio the Decrepit"] = {
		["You are certainly a long way from home, $r."] = "be880edf442fc7e0b0b1b9c84872c4c9"
	},
	["Niby the Almighty"] = {
		["Bow in my presence, insect! Surely you can feel the power I hold over you."] = "283fc5c382b274b565983a110dfbcccc",
		["So you have come to Niby to learn the secrets of calling down an infernal servant from the Nether.$B$BSilence! Niby knows all!$B$BNiby is not so quick to part with such knowledge. First, you must assist Niby with a very important task."] = "35284cfba5849c0b76c8dffde030b428",
		["There is a powerful infernal named Kroshius northeast of this camp. It is why Niby is here. Kroshius is a greater infernal - an infernal that has lasted longer than expected. You see, nub, an infernal crashes down into the earth with great intensity to serve its master but this intensity fades fast. Once the blazing flames have died down, the infernal crumbles."] = "1d846f3de3583986c12a82cbfed8b313",
		["Do not interrupt Niby, fool! I shall rend the flesh from your bones and use your skeletal remains as a coat rack. Now where was I? Oh yes, so, Kroshius lasted nearly ten times longer than any ordinary infernal. I am not sure why but I am confident that with enough study, I could find out.$B$BI need you to recover Kroshius' Infernal Core."] = "71cbe27cb3eb26c72fce94d8e5036a76",
		["If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.$B$BMy imp, Impsy, shall set you on your way."] = "0f171e609c3286086cdc7254621214ab"
	},
	["Short John Mithril"] = {
		["Arr!   There be nothin I like to see better than folks fightin to the death in the arena.   If you be here at the right time maybe you can be one of them!"] = "25938481b6c048114f6758db91eca1de"
	},
	["Ulathek"] = {
		["Be gone!  I hold counsel with Dreadlords, and the matters we discuss are not your concern!"] = "09af5cd652b4864bff857c89022d0037",
		["... A message from Banehollow?  What message is that?  Does he have need of his great advisor and servant, Ulathek?  Does he require my presence?"] = "d02f8235c277c2ac91b7975819950acb",
		["What?  But how?  No!  This is not possible!  I have been so careful... he could not know!$B$BYou lie!  You lie, and now you'll die for your deceit!"] = "0895ca3a8270e33abe5027f593574c7e"
	},
	["Simone the Inconspicuous"] = {
		["What a wonderful day to be alive! Look at the beauty that surrounds you, friend. Enjoy what life has to give!"] = "8b502b68ad7c1440c417be31792c62c9"
	},
	["Precious"] = {
		["*GRRRR* *RUFF* *RUFF*"] = "51263da3c99047105d9c1b6fde4742f6"
	},
	["Franklin the Friendly"] = {
		["Lava? Pay no mind to all of that, friend. Look around you. Take in the joys that nature has to offer."] = "be537ba486583fefdcc4b0e7880c13fb"
	},
	["Artorius the Amiable"] = {
		["How wonderful to see another person in this remote region of the world. Come, walk with me. Let our bodies keep each other warm."] = "592e299bd0edf1ea20bdb5dabf705526"
	},
	["Nelson the Nice"] = {
		["I come to Silithus every year around this time. The weather is phenomenal for my bunions.$B$BYou should take a stroll with me, friend. Enjoy the sights and what not."] = "5e0b696d989d9f556038cd140846f661"
	},
	["Master Smith Burninate"] = {
		["Burninate's the name, smithin's my game... and, erm... I sell a little food and water on the side. Care for some meat?"] = "cf73090a6937f1713ac6d2eb671f2040",
		["You've done all that I've asked you to do, $n. There's really nothing more here for you. If you are interested in continuing your career as an agent of the Thorium Brotherhood, speak with Lokhtos Darkbargainer at the Grim Guzzler in Blackrock Depths.$B$BFarewell!"] = "bff732f0c9b0a483ea8280c43a9f40de"
	},
	["Overseer Oilfist"] = {
		["Welcome to Thorium Point.  As Overseer, I'm responsible for all the activities of the Thorium Brotherhood.  While that mainly involves mining, smithing, and some minor guard duty, we've lately become more of a martial organization... out of necessity."] = "669f781e499c1b23be066d12915fc12f"
	},
	["Taskmaster Scrange"] = {
		["As acting Taskmaster of this here compound, it is my duty to make sure that there is a certain level of tedium involved with all forms of business, work, rest, and relaxation that may take place here.$B$BIf you find anything that you are asked to do to be too easy and hassle free, report to me immediately."] = "793ee16511d200a9b8cd0eb76fa5bc51"
	},
	["Hansel Heavyhands"] = {
		["When Lolo doesn't wanna spill any o' his precious ale or get his lil' dress dirty, I'm called in. Yep. Ol' Hansel is the dwarf they use to mete out a lil' bit o' justice an' a whole lotta pain."] = "bd3faf4cde31a3db3276cfa61a84692d"
	},
	["Evonice Sootsmoker"] = {
		["We chose to leave the protection and comfort of the Depths to exploit... er, I mean... hrm, yes that's right, EXPLORE the world."] = "26996ccc4e6778d1800c2c92dd4dc550"
	},
	["Lookout Captain Lolo Longstriker"] = {
		["Yesh, it'sh true, I'm blind as a bat! An' drunk as a ... err, drunk as shomething that getsh drunk.$B$BI'll tell you what, $r. It'sh the drink that keeps me shenses sharp. It'sh common knowledge that when you lose a shense, yer other shenses become more alert. My drunk shense is incredible these days."] = "7dbd9d808230424267a5e8139bdbae10"
	},
	["Zorbin Fandazzle"] = {
		["Well hello again, $n!  I don't know how much longer I'm going to keep on trying to set up a shop out in the middle of nowhere.  Still, since you've helped me out in the past, I'll show you some stuff you may find interesting!"] = "35ce1445970071ba504febea09ce9bc3"
	},
	["Field Marshal Afrasiabi"] = {
		["Move along, citizen. There is nothing to see here."] = "44f7bf8eff87d3a469dce6889fc22ef9"
	},
	["Clavicus Knavingham"] = {
		["Friend - Stormwind needs your assistance and your generosity!$B$BOur once large stockpile of textiles has run critically low.  Stormwind is now engaged in a multi-pronged effort to rebuild those stocks for the manufacture of textiles and bandages!  Your donation of cloth would help Stormwind immensely, as well as earn the respect of the citizenry!"] = "57a0cf3e383340429113af3746750413"
	},
	["Mistina Steelshield"] = {
		["Aye, you there!  If you want to earn the respect of the dwarves of Ironforge, then you can start by donating valuable resources!  Ironforge finds itself running low on cloth piece; textiles and bandages don't grow on trees, ya know!$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the dwarven people of Ironforge!"] = "c798a1ce537b25ff52e8a52d1ed3af2a"
	},
	["Bubulo Acerbus"] = {
		["The exiles of Gnomeregan find ourselves in even more dire straits by running low on cloth reserves!  Perhaps you can help us, eh?!$B$BBring me extra cloth pieces you might have to help us replenish our stocks.  By donating them, you'll be earning the respect and trust of gnomes everywhere.  That's something that money can't buy!  Well, I guess cloth does, but that's beside the point..."] = "6b524e6f63821d7aa775800797480d02"
	},
	["Raedon Duskstriker"] = {
		["Hail friend - a moment of your time, if I may...$B$BWe have endured much in our trials and tribulations in establishing Teldrassil.  Were the constant strife of the times not enough, we now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of night elves everywhere in helping us out!"] = "f1bba8b8fe977e9469a2a2d8535cd5bc"
	},
	["Rashona Straglash"] = {
		["In these trying times, a simple donation of cloth can go a long way to help those less fortunate than ourselves.  Cloth goes a long way to making garments and bandages - both important for the war effort!$B$BIf you are interested in donating cloth pieces to the orcs of Orgrimmar, I will gladly accept them and make sure you receive the proper recognition for doing so.$B$BFor the Horde!"] = "8c358b35413bf96fe889092366c26195"
	},
	["Vehena"] = {
		["Aye, you there!  If you want to earn the respect of the Darkspear, then you can start by donating valuable resources for those in need!  Textiles and bandages don't grow on trees, ya know.$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the Darkspear!"] = "fcd9c2164c91cf223aef5987fbacf8ff"
	},
	["Rumstag Proudstrider"] = {
		["Hail $g brother : sister;... I'd like a moment of your time, if I may.$B$BWe tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!"] = "804dac15ce73451780e4cf2e731b64fd"
	},
	["Ralston Farnsley"] = {
		["You there... it is in your best interest to aid the Forsaken during these dire times.  Listen closely, as I dislike repeating myself.$B$BWe currently find ourselves in a dire shortage of cloth.  Bandages and simple textiles are running low, and donations are being accepted to bolster sagging inventories.  While you'll not receive financial compensation - hence what donation means - your aid will not go unnoticed."] = "142f4365ed15cdab171cacd75afb66fc"
	},
	["Lard"] = {
		["Lard keep peace here. Lard also sell fish. Want fish?"] = "04e4383abd93bf0df0591a3a27f977a2"
	},
	["Sentinel Farsong"] = {
		["The battle for Warsong Gulch is a battle that we cannot lose.  We fight for our honor and we fight for our land, and no orc or misguided ally will take them from us!"] = "9701a4e7da22327ecb2b934e24b01980"
	},
	["Smith Slagtree"] = {
		["If it's broke, Slagtree can fix it!"] = "51031711691097d768356cfcd57947ae"
	},
	["Otho Moji'ko"] = {
		["I've got all the cooking supplies you'll ever need, mon!"] = "a50e2b4b7312975593a68ec06810dec3"
	},
	["Katoom the Angler"] = {
		["Fishing is just so pleasant, mon. You know? I owe my state of bliss to my mentor, the greatest angler in the whole world - Nat Pagle. Have you heard of him, mon?$B$BIf you be looking for enlightenment, Nat Pagle be the one who gonna show you the way. "] = "22cfa7ff979d73b2dcf77d76511c1aae"
	},
	["Huntsman Markhor"] = {
		["Zul'jin shall return one day, $r. Mark my words. Until then, we all hold our positions and do what we can to keep the forest troll population intact.$B$BWith that said, as master huntsman of Revantusk Village, it is my responsibility to ensure that the world around us is safe for habitation.$B$BThe beasts of this area must be kept in check.$B$BAre you looking for work? "] = "76deb74443da4575525874ac17cb68a3"
	},
	["Zap Farflinger"] = {
		["I have just completed a new dimensional imploder that will make me rich beyond my wildest goblin dreams!   All I need to do is get a skilled Goblin Engineer to build a dimensional ripper that connects to it and try it!  "] = "0c3633a7d4f6e9b798ba0e339ff2765c"
	},
	["Jhordy Lapforge"] = {
		["With some of the technology that was recovered by bold gnomes venturing into Gnomeregan, I have managed to construct my greatest invention:  The Matter Transporter!    All I need now is a skilled Gnomish Engineer to build a powerful beacon attuned to the transporter."] = "31e604263a5a40b23254a6b2433c24d0"
	},
	["Elder Torntusk"] = {
		["Get the key and unlock these chains! Hitah'ya the Keeper holds it... back of cave... "] = "6cb44e40e1eee423968a03c8809dd13a"
	},
	["Captain Shatterskull"] = {
		["It is no easy task to protect the Horde's lumber gathering efforts here in Ashenvale, but we have never shied from battle!  The night elves and their allies will fall!"] = "79b85c8b9c23c4e542b6d52221827c9e"
	},
	["Sayge"] = {
		["I have long known you'd seek me out, $n.$B$BEvery sentient being in this world is driven by the choices they make.  Choices beget further choices, and these in turn make someone who they are.  This is where your fortune is drawn from - who you are, and the choices you make.$B$BAre you ready to discover where your fortune lies?"] = "ffc0e5a989f2121fa6507a9710ef4d1b",
		["Very well then...$B$BYou have been tasked by your liege to guard his fields of corn from poachers and thieves.  One night on patrol, you stumble across a haggard man in thread-bare clothing stealing corn from the field.  You quickly confront him, and he immediately begs for his life.  He claims he is stealing the corn to feed his family since the lord of the land - your liege - demands too much in taxes.  Your liege is indeed known for his harsh taxes throughout the land.$B$BMake your choice."] = "31d1913bc622fe704585cab3b687edd2",
		["Your next choice awaits.$B$BYou are the sworn executioner for your liege.  A man has been sent to you for execution as a traitor of the liege and your people.  You know this individual as a close, virtuous friend who mysteriously vanished one day.  You also know that the man's crimes for which he was convicted supposedly caused the deaths of many innocent civilians.  Upon seeing you he begs for his life, claiming he was framed by a higher authority.$B$BMake your choice."] = "4eb9271494c89014e8bd578d81057cc1",
		["Your next choice awaits.$B$BYou are on a diplomatic mission for your liege to a cruel country that is currently at war with yours.  The war has been costly on both sides.  Your mission is to secure a peace that is honorable to both peoples.$B$BAt a diplomatic dinner, you overhear the ruler of the opposing land viciously insult your benevolent liege.  You are fairly certain the ruler meant to say it out of your earshot, but nonetheless he has besmirched your liege's honor.$B$BMake your choice."] = "80a3051735494f9c68e499a8cfc9bab5",
		["Your next choice awaits.$B$BYour brother seeks to join the ranks of the prestigious military order you are already a part of.  While you are sure of his commitment and loyalty, his talent and ability to perform the arduous tasks of the order is what you question.  While you are not certain he will be able to rise to the challenge of the order - putting you and others in danger - you are certain that your word alone would allow him in or keep him out.$B$BMake your choice."] = "73e1a7f7827202ea470fb2bd083d12d6",
		["Your next choice awaits.$B$BYou alone have defeated a terrible beast that has been ravaging the countryside, taking its ear as a trophy.  You later learn that your liege had offered a reward for the beast's death, and that a kind but destitute knight who you know is trying to support a family by meager means claims the beast's kill as his own.  You have no real need for money yourself, but you know that the destitute knight is lying for his own personal gain.$B$BMake your choice."] = "f46e1546b8277b043fa551a09d391ab1",
		["Your fortune is cast, $c.  For the next few hours, you will find your spirit in tune with your true nature.  Be careful, as your fortune - and your fate - are never as clear as you might think them to be.$B$BIf you would like a small glimpse of something to ponder in your future, by all means let me know.  I'd be happy to give you a written fortune, provided you have room in your inventory.  It is one drawn from the insight you have shown in answering my questions."] = "ee877a0798084091f071a19e0f87d089"
	},
	["Silas Darkmoon"] = {
		["Greetings my friend, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!"] = "bcc4137261fe1b6312ba537a58e54584",
		["It's not always about money, clem!  While we receive generous donations - some extremely substantial - our traveling troupe of performers is fueled creatively by a need to brighten this war-torn world.  Don't worry about us, but instead let us worry about how to best entertain you."] = "da58ab9e957f7ab42ce16f524fdbbaaf"
	},
	["Burth"] = {
		["Unlike most ogres, I do know what an outhouse is for - giving you a swirlie.  Now beat it."] = "7553378b70f3ffed0071880696d048ab",
		["I lived in Dire Maul for a little bit.  That was fun.  Really."] = "cbded609896573f791cf552b906ab7f3",
		["I need a second head like I need to lose my first one."] = "4f78b70a8aed6265ba580f546599a1f7",
		["You mess with Silas, you mess with me.  Have a nice day."] = "8673b36116f617e8a07feed4c658a007",
		["In case it wasn't obvious, I'm not here for customer relations."] = "d0ef954cf8f63392c9857b8006ea0a40",
		["If you're trying to be friendly, save your breath.  Better yet, just stop breathing all together."] = "585d229f68633051d8dcfdf6c0cd42a2",
		["This ain't a ride, clem.  Beat it."] = "79a3756e99d2c2656a6e5df51f87981a",
		["Move along, rube."] = "9610cb6715b051a351840784f52958de"
	},
	["Gelvas Grimegate"] = {
		["Ticket redemption here!  Get your tickets turned into prizes!  Step right up!"] = "41e1418f674fe4ab79111719d0059787"
	},
	["Yebb Neblegear"] = {
		["Welcome!  Welcome to Yebb Neblegear's Darkmoon Zoo Bizarre - a Trove of Living Legends and Mythical Oddities!  Enjoy your visit, friend!$B$BBut be mindful of what you touch!  These exhibits hold artifacts and beasts both dire and divine!  They might burn the wayward hand of an over-curious onlooker..."] = "7b6f88d5a16eec48ed71f32561eef2a6"
	},
	["Kerri Hicks"] = {
		["Welcome to the Darkmoon Faire, $c!$B$BMy name is Kerri Hicks and I'd shake your hand but I'm afraid I'd break it, because I'm the strongest woman alive!"] = "9b981643b5259e425303da2848d7e277"
	},
	["Chronos"] = {
		["Greetings.  I am Chronos - He Who Never Forgets.  My memory is without flaw, and exact to the most minor detail.$B$BTrust me."] = "26f2988f1c71f43761398daa16273de5"
	},
	["Rinling"] = {
		["Hello!  And welcome!  I'm afraid my booth is not open... many repairs are needed...$B$BBut I am still bound by blood oath to put a smile on your face.  So please, smile, or I must cut off my hand and consume no living flesh until it regenerates..."] = "dcf71fd938957989dca86c245fa95f64"
	},
	["Melnan Darkstone"] = {
		["Boys and girls - children of all ages - the Darkmoon Faire has arrived!  Huzzah!"] = "b4715bed2d4172b99afe64138b478e15",
		["The Darkmoon Faire will only be live for a short time before the curtains are drawn closed.  Be sure to visit it today!"] = "864aaa5f97ede0b83eddc24aeea8facb",
		["The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see!"] = "7f501b39fa30f5f4e24ee08fe9eba2df",
		["It's here!  The Darkmoon Faire is now open for business!  Be sure to see the most exciting show on all of Azeroth!"] = "87545a17514f8d22ebc68ca9371a6f4f",
		["The Darkmoon Faire is right now located in Elwynn Forest, just south of Goldshire.  Don't miss it!"] = "a3b2f7b279774ca4d85f4efbcc996fb0"
	},
	["Kruban Darkblade"] = {
		["Step right up and hear about the most amazing spectacle in all of Azeroth - the Darkmoon Faire!  Huzzah!"] = "5a260aa92b38ae89795e971a54fac630",
		["The Darkmoon Faire is coming!  There is fun for children of ALL ages!  Come one, come all!"] = "f55a4bb137f50ce95546335186980a53",
		["Be sure to catch all the amazing sights and wonders of the Darkmoon Faire when it comes to town!"] = "2d62b0fff2691d1f7dd1c29f59793a31",
		["The Darkmoon Faire is coming to town!  Don't miss it!"] = "64ed669f2c530fdee40a973f494727e3",
		["When the Darkmoon Faire opens, it will be located in Mulgore.  We'll be pitching our tents just southwest of Thunder Bluff!"] = "1a25e293039b93cebbb2befb5b4159a9"
	},
	["Sylannia"] = {
		["Just in... another batch of Darkmoon Special Reserve.  Come get yours before they're all gone!"] = "a1cdb9f0073b916776c053aaf793a2bb",
		["Tips are always graciously accepted, friend."] = "7fb4098049b4c3596d12b8795d24c345",
		["Don't be shy, buy a round for everyone!"] = "05dd55fc3499fcacc3e60a02e7dbbfe6",
		["Tasty drinks for sale!  Quench your thirst on some of the Darkmoon Faire's finest brews!"] = "3999eb39e5a6b4a8ebbe3d52dc37db02"
	},
	["Stamp Thunderhorn"] = {
		["For a limited time only, crunchy frog available exclusively here at the Darkmoon Faire."] = "59d2d4fff147043a75626e0a7a8383d9",
		["You've got money and we've got food.  What are you waiting for?!"] = "9719b872df7a6d658059c4efb6a6eab8",
		["Darkmoon Dogs fresh off the grill.  Come and get 'em while they're hot!"] = "7ed7c6b19e06f30b7e99de7f3e4e43d0",
		["Step right up!  Get your red hot wings right here!"] = "a0865f7e679cbc713d639fbb652b59b9"
	},
	["Lhara"] = {
		["Have you any idea what I go through to bring these incomparable valuables to sell?  Come see them all for yourself!"] = "094cace1e1f8bca5aca039f124ce8236",
		["Come and take a look at my wares while you still can.  We're here all week, and then we're off to some far off land."] = "1e3edd109eb58225d62d1478f6ff6d54",
		["Darkmoon Faire Cards?  See the Professor here for those."] = "76453a460adc20ee0230c173d4da51fa",
		["Every item that I have for sale I acquired myself.  You have my personal guarantee of authenticity."] = "29c5fcc54f30c3265fc0ea1499ea23af"
	},
	["Professor Thaddeus Paleo"] = {
		["Welcome to the faire young one!   We have collected wonders from all over the world for your perusal.   Oh and please let me know if you manage to collect a set of the lesser darkmoon cards, as the master... I mean I would be keenly interested in them."] = "9d9f28d8b7f42644f97dadbf6f5ddac4",
		["We have seeded darkmoon cards around the world to see if any worthy individuals could complete a set of any of the eight suits.  If you manage to collect all eight cards of one of the suits we will reward you with one of the greater darkmoon cards that functions as a powerful trinket as well as a link to the Darkmoon Faire."] = "36a2e21d2bb8e9b2c54205d46968adcc",
		["If you manage to complete a deck of beasts cards you will be rewarded with a greater darkmoon card of the blue dragon.   This is very useful in restoring of magical energies."] = "f9fbc218ea70279123d05e8059b07a52",
		["If you manage to complete a deck of portals cards you will be rewarded with a greater darkmoon card of the twisting nether.   This card will occasionally pull your spirit back into your body after death and restore you."] = "cabe10467ba55951a39c5efc5b01e754",
		["If you manage to complete a deck of elementals cards you will be rewarded with a greater darkmoon card of the maelstrom.   This card will occasionally impact an enemy you are fighting with for heavy damage."] = "6c0066e9c134f9932cf5d4baf797844d",
		["If you manage to complete a deck of warlords cards you will be rewarded with a greater darkmoon card of heroism.   This card will occasionally heal you while you are engaged in melee combat."] = "5b4d4908a2259afea5d5edad7b0cb6e5",
		["If you manage to complete a deck of furies cards you will be rewarded with a greater darkmoon card of vengeance.   While wielding this card anyone who strikes you has a chance of suffering holy vengeance."] = "0df1f0f7ecdc394e5f819fa811fd85c3",
		["If you manage to complete a deck of lunacy cards you will be rewarded with a greater darkmoon card of madness.   The power of madness will fill you each time you slay an enemy."] = "d102502e97768dd5377432fdaf2189a1",
		["If you manage to complete a deck of blessings cards you will be rewarded with a greater darkmoon card of crusade.   This will increase the damage you do with your spells and attacks as you continue to fight."] = "f96e18ce4e4d5fb9645c96b915cf627a",
		["If you manage to complete a deck of storms cards you will be rewarded with a greater darkmoon card of wrath.   This will increase your chance to get a critical hit with spells or physical attacks until you achieve one."] = "67f5e762b4076d79e56091cf6dddd7bc",
		["You are astute to ask, young $c.  Scribes are capable of inscribing tarot cards of great power, although even they do not have full control of what they make.  The fates decide for them.$b$bIf you manage to obtain a completed deck, please bring it to me for a magnificent reward."] = "955f89b61bd8c146c63a98cad95c55f2"
	},
	["Darkmoon Faire Carnie"] = {
		["The Darkmoon Faire is the greatest event on all of Azeroth!"] = "8cf0cb9b1a653b125c194f3e0135725a",
		["Don't forget to buy refreshments and souvenirs!"] = "a4ffb5174d41980f407bb60bccee4e12",
		["Having a good time?"] = "eea347b00420ee2f9f8c495a6fa444f3",
		["Sure are a lot of litter bugs around here."] = "8ae59f0d6ec8b25bf7b938f55e8efe2c"
	},
	["Flik"] = {
		["Frogs and leather balls for sale!"] = "f046116068fc4d1e9e457e15a748f10a",
		["Get back here!"] = "08987dcbd2c60ebaceddbe453b076532",
		["It's getting away!"] = "3aaecbaa61c058540a7d4b56beda045e",
		["Hey, someone help me catch this thing!"] = "956e57d432d20f95c80a752a9d07a848"
	},
	["Flik's Frog"] = {
		["Kiss me."] = "08a25b153f7e1c9f3527f1961e34b1fb",
		["Ribbit."] = "f570dc84f7eeeda220750b80a6917f8c"
	},
	["Morja"] = {
		["I can't find my pet frog, Jubjub.  She loves Dark Iron Ale, it's all she ever drinks, but can be so hard to get!  Now I'm out... and Jubjub must have run away to find more!$B$BI wish she would come back..."] = "973e2ce5b84bdcdcff9a070880e9f347",
		["I'm so happy that Jubjub returned!  I only hope that I don't run out of Dark Iron ale soon, or I fear my pet frog might once again escape!"] = "e3a9bceac350c8d4521ba30052baa2de"
	},
	["Molthor"] = {
		["If you have come to save the world then you have come to the right place. The faceless one - the Blood God, Hakkar - has been brought back into our world!"] = "36ed78ad0299f724a3f13e2686290432"
	},
	["Jin'rokh the Breaker"] = {
		["I am Jin'rokh the Breaker, envoy of Mugamba: Fist of Rastakhan!$B$BMy dealings are with warriors and heathens."] = "a46367cc86625cea805d07b70aa707b6"
	},
	["Al'tabim the All-Seeing"] = {
		["I am Al'tabim the All-Seeing - an envoy of King Rastakhan.$B$BMy dealings are with priests, mages, and warlocks."] = "c28cac378192770c4a9166d049115821"
	},
	["Maywiki of Zuldazar"] = {
		["What you be expectin', mon?$B$BMaywiki only be dealin' with the druids and shaman."] = "170ffaa87dbcca087ef37ce1bfd1b76c"
	},
	["Falthir the Sightless"] = {
		["Sightless I may be, but vision I have.$B$BMy primary dealings are with hunters and rogues, $r."] = "ec7eecf7af72db521e56383587d7714a"
	},
	["Exzhal"] = {
		["Greetings, $c.  I am Exzhal, Servitor of Rastakhan."] = "e7cdb9be91ab5ee24261c54b7949c919"
	},
	["Rin'wosho the Trader"] = {
		["Hail, adventurer. I am Rin'wosho, trader of Zuldazar. I come from the South Seas and bring many exotic goods and items from my homeland.$B$BPerhaps if you prove your worth to my tribe, I shall barter.  If you have any of my tribe's Honor Tokens, then perhaps we shall barter even more."] = "aca6701e63f56de998a1cc492839d1c2"
	},
	["Kartra Bloodsnarl"] = {
		["I am sorry $c, but you need to be more experienced before you can survive in Alterac Valley."] = "6f8cf301e3f0ef7063dfca782d98b50f",
		["Lok'tar $c!  We have need of your services in Alterac Valley.  Shall I add you to the lists?"] = "dab0c064dd61d01fde511ec075b693a7"
	},
	["Elfarran"] = {
		["I am sorry $c, but you are not seasoned enough yet to enter Warsong Gulch."] = "db6d2a2e49b804a2cf643369c2d678f3",
		["Hail to thee $n.  Do you wish me to aid you in your journey to Warsong Gulch?"] = "7b7d94a359c45dac8bad00353884b2f8"
	},
	["Lylandris"] = {
		["I am sorry $c, but you are not seasoned enough yet to enter Warsong Gulch."] = "db6d2a2e49b804a2cf643369c2d678f3",
		["$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?"] = "dd959e61c698ff0b58943c6cce1a774d"
	},
	["Field Marshal Oslight"] = {
		["The League of Arathor has sworn to retake Arathi for humans of Stromgarde and the Alliance.  It is a battle hard fought, but a battle worth fighting."] = "8f58e6676f208553898ca627001b851f"
	},
	["Sergeant Maclear"] = {
		["To win this war, we can't sit idle and let the tides sweep us over.  We must strike, hard and fast, or Arathi will never again be ours."] = "2d10a0bf75c6c86698196a262967b949"
	},
	["Defilers Emissary"] = {
		["You are not yet powerful enough, $c.  Move along."] = "205f1ffebfd60deb4bc5bec05e2d290a",
		["Our need for assistance in Arathi Basin is greater than one might imagine, $n.  So too is the honor and reputation one might acquire there in this time of need, however.  I implore you to seek out the Arathi Basin battlemaster in this city."] = "6e0170992d6cf009a32b12d501fc5d6f"
	},
	["League of Arathor Emissary"] = {
		["While exploration in these new lands is no doubt important, you mustn't forsake Azeroth! We need you now more than ever in the fight against the Defilers. Those resources must be secured!"] = "b831c1e6b6fbc04fc562ff4b6e4bdbc3"
	},
	["Deze Snowbane"] = {
		["I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin."] = "1bd3c817720e43bbc720fa8704b7cdfe"
	},
	["Sir Malory Wheeler"] = {
		["I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin."] = "5d7befc434c3b284ff699c9b717bf554",
		["Look around you $c.  You are in rare company to be certain, yet still I think you need to prove yourself.  Hmm, perhaps I shall allow you to aid us in our cause at Arathi Basin.  Would you like that?"] = "d434eab0594d28c2d08ea9dbd4f04fbe"
	},
	["Lady Hoteshem"] = {
		["I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin."] = "c3b7867dcd5ddb0aafe672da55946ea2"
	},
	["Wagner Hammerstrike"] = {
		["Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.$B$BPlease feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year."] = "20a2672934e46dd87b9f9e585c09dd52"
	},
	["Javnir Nashak"] = {
		["Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.$B$BPlease feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year."] = "07d82752c2b2a676dc03af347776f8b3"
	},
	["Deathmaster Dwire"] = {
		["We must not allow the Alliance to expand their power base in Arathi!  Even their miniscule Refuge Pointe may one day grow to threaten us."] = "a0cdf795929fa807da0b88c05e1206cd"
	},
	["Deathstalker Mortis"] = {
		["The battle for Arathi Basin is a battle for resources.  Lumber, ore, food... all these are needed in order to wage a good war.$B$BDenying our enemies of their supplies is as good as killing them on the battlefield."] = "903cc7768c784eb239105149e250dee2"
	},
	["Zanza the Restless"] = {
		["I am Zanza, a Loa of Zandalar. I have come in this ethereal form from Zandalar to help my people. Hakkar has no dominion over my soul.$B$BI help those that have helped the Zandalarian people."] = "c8103fbcbe2d18f0cdfa4d909fa00e81",
		["A friend of the Zandalrian! You have ventured deep into the lair of the Blood God, $c. You will do well to listen to what I have to say.$B$BMany thousands of years ago, while the indigenous trolls of the Zul'Aman empire were battling the invading high elf heathens, great magic was stolen from Zanza. This magic was used by the high elves to enchant their weapons and armor to assist in conquering the trolls of the region."] = "4ac21e5139c32c1e66826abe3382f829",
		["Have you? Then you know how weak and pathetic the high elf version of troll magic was?$B$BThe high elves could not understand why a people with their magical affinity could not contend with the powers of troll voodoo. This was an inconceivable notion for the pale skins to understand. They were resigned to using the bastardized version of troll enchantments. I believe they called them 'Arcanum.' "] = "0f2be05ebc4b746b42891e97a2db2629",
		["Zanza can create the ancient troll enchantments with the right components. This magic will help you in defeating Hakkar and his minions.$B$BI only ask that you bring me two items."] = "422211fe9697e4c260bda5b4ed73aa57",
		["The first is a primal token that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.$B$BThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed Hoodoo piles.$B$BBring me these things and I will create a powerful enchantment for you!"] = "5951443b219460226c4b5ed7e2d1b85d"
	},
	["Zandalarian Emissary"] = {
		["We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world.$B$BThe leader of our expedition, Molthor, brought us to the Yojamba Isle, along the northern coasts of Stranglethorn, and even now recruits brave heroes to venture into the ancient troll city... Zul'Gurub."] = "2b07aacfb7ec7aa8d2c6dc58fbefae37",
		["We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world."] = "1f1240f397272066c8c27e743889f53c"
	},
	["Riggle Bassbait"] = {
		["We already have all our winners for today's contest, but Jang is willing to purchase any Tastyfish that you have fished up! There's always next Sunday for you to show your angling skill!"] = "c8ac00e6867c08cc533bd9da460298d3"
	},
	["Jang"] = {
		["Fishmaster Bassbait has had the waters here seeded with high quality Tastyfish so he can have his tournament. Once he gets his winners, I will give you silver for each five Tastyfish you bring me!"] = "b588ee06d553496733745bc2d921792d"
	},
	["Fishbot 5000"] = {
		["*Whirr* *CLANK* I have been instructed to accept high quality rare fish and return valuable Nat Pagle fishing accessories.   Fish Requested. *THUMP* *Buzz* "] = "c2623fabc9fad7a6c1f934fd35782b88"
	},
	["Silverwing Emissary"] = {
		["$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?"] = "8c59b436d4f8db5f6a0c712f93e98b11"
	},
	["Stormpike Emissary"] = {
		["$n, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?"] = "652b981993757876fc31ffb1c317b7e2"
	},
	["Warsong Emissary"] = {
		["$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?"] = "c88e285b542b71094d53a278fe6d7d2c"
	},
	["Frostwolf Emissary"] = {
		["You need to be a stronger $c before you can help us in Alterac Valley."] = "b69be5e5edb23a5a91ccfe01c11024bc",
		["Hail, $c.  There is a great need and even greater honor and renown to be had in Alterac Valley at this time. Will you join our fight against the Stormpike Guard?"] = "2cc8ab930b44e6b2d04235a744864409",
		["Strength and honor, $c. We need eager soldiers like you in Alterac Valley; the territory of the Frostwolves must be defended! Will you return to Azeroth and lend your aid?"] = "99e16b9ab7d751c7c66e0034b74b3adf"
	},
	["Grinkle"] = {
		["Heya Heya Heya!   If you want to test your fishing skills then I have just the place for you!   This Sunday we have a fishing tournament in Stranglethorn! "] = "6f639c78318d6f4246c13de6e741b795"
	},
	["Barrus"] = {
		["Well met master of Rod and Reel!   If you be willing to test your skills against the best fisher-folk in the lands then listen up!   On this very Sunday there be a contest in Stranglethorn where the master angler will be chosen! "] = "c93642180929f10459742e06d16d95eb"
	},
	["Qeeju"] = {
		["Greetings, $c. I can help stable your pets or assist you in recovering lost companions."] = "ed642b9484f9501b200c90d72260f950",
		["Greetings, $c. I can assist you in recovering lost companions."] = "f751c5bafb56e623245a60f42259cb73"
	},
	["Ralo'shan the Eternal Watcher"] = {
		["Greetings, traveler. It was here, nearly 1,000 years past, that the Qiraji began their march of destruction across Kalimdor.$B$BThousands of lives were lost during the war, most in this cursed desert during the initial invasion.$B$BI am one of only a few that remain, chained to both the past and the present. I know not why I am to remain stationed here but I know that I must."] = "0b0c533904f5ec72051ce930ebe18a3a",
		["I have been slain a hundred times. I always wake here, alive. Some say I am cursed and others..."] = "06b81739f0bafcfd039de7bee1020205",
		["They say that I am blessed: A herald to harken in a new age."] = "2e00e741fec447902b6e157a134f4866",
		["Ancient forces stir - forces that have not been seen or felt for thousands of years. The world weeps, $r. Perhaps a new sundering comes. A sickness born from within...$B$BThe foulness has begun to seep into our lands. From the Dream come nightmares. Nightmares to befoul us in our waking hours... "] = "b046831149354fece411cd5757825f3a"
	},
	["Rutgar Glyphshaper"] = {
		["Look up to the heavens, $c. The Dragonflights have not been seen in this area for a thousand years! Those Qiraji are up to something, I just know it!"] = "af0fd13734bbd749a52d7d45abe934d3",
		["You best have a seat then, this is gonna be a long one.$B$BWhen we initially arrived in Silithus, Mistress Mar'alith was the first of the night elves from Cenarion Hold to join the expedition. Our routine was nothing out of the ordinary: Form a party to venture into the various hives and search for lost artifacts. "] = "443b87cdae07e4c1b2c9da0ebeb77760",
		["It sure is! Those hives were abuzz with various silithid that were none too happy to see us.$B$BEverything was going fine until we came across a glyphed crystal in Hive'Regal. She was drawn to it like a moth to a flame! She put her pretty little cheek up against the crystal and instantly entered a trance-like state. Naturally, this worried my crew. We picked her up and carried her out of there with a quickness!"] = "81794f3c4756bdfd389fa69ab46e362c",
		["We took her to the Commander with hopes that the druids of the Circle could fix her up. Sure enough, they were able to wake her up. We figured our business with the Circle was done and we could get back to work.$B$BA few weeks passed and everything was going fine. Brann was still around back then so we had a bit of order in our work structure. Then one day, out of the blue, she appeared back at our camp. "] = "9e37db370c5a046827955e725e64bdd6",
		["Are you daft? Who else would I be talking about? Yes, the girl - Mistress Mar'alith. Anyhow, she was back and not in too good of a mood. That's when the demands started flowing. "] = "226398c6e0111e0a06eca54612ddddec",
		["She demanded that we immediately head back to Hive'Regal! Brann would have none of that sass. He told her that there's no way we would go back into those hives without an army backing us up. It had gotten far too dangerous. The number of those stinking insects seemed to have tripled from when we first ventured into 'em.$B$BThat's when Natalia lost it!"] = "4a04ba2b3a44d86c49e14414d314fd81",
		["What do you mean what do I mean? She went nutso! The girl went straight crazy on us. Now ordinarily I don't hit girls but after I recovered from the blackout, I was pretty damned angry. Brann, Rutgar, me and the monkey went positively orc on her! It's a miracle we were able to fend her off. She seemed almost possessed!"] = "9192ce03c16bdad9e3e38652c3d3ce23",
		["Who knows? Anyhow, that was the last I saw of her. Maybe Frankal can give you better information.$B$BNot to steer off topic here as I'm sure the work you're doing for the Commander is important, but we're onto something huge here. HUGE! Our requests to Ironforge for an army have so far fallen on deaf ears. Apparently we're stretched too thin in protecting the realm or some such nonsense. Once you take your report back to the Commander, come back down here with some friends. We need your help!"] = "dea537ea78bde91b9c77ce8d552d9bb7"
	},
	["Frankal Stonebridge"] = {
		["Bronzebeard's gone missing again! That dwarf sure didn't get any of his brother's good senses."] = "2e9da6b3338a01eeae4e67b707bbd7e8",
		["Oh brother, not this again... Have a seat $g sonny:missy;.$B$BI'm sure Rutgar has told you some of this story already so I'll spare you the boring details and get right down to the nitty gritty."] = "8b65201c7f8e4fca254e87dde37a2d5b",
		["Right then! So the Mistress had come back for a second go at the hives but Brann was having none of that nonsense! Before the melee began, she started talking to something or someone. Crazier still, she started chanting in a language none of us had ever heard."] = "385c489f30a4498700047ccea1cf59cc",
		["You're telling me! It's even stranger considering between Brann, Rutgar, me and the monkey, we know 38 different languages including a touch of Titan - both Vanir and Aesir.$B$BSo anyway, whatever she was click clacking about, it definitely wasn't with anyone 'present.' She then nodded and went on the offensive! Attacked us outright!"] = "86d25b257a6e22384810cb2de77de42a",
		["Listen $g sonny:missy;, I'll have you know that whatever attacked us was no priestess of nothin'! Her eyes were aglow with something evil and she was genuinely frothing at the mouth! She came in, did some kind of crazy scream that sent us all runnin' in separate directions then started flayin' our minds one by one. I'd be hearin' shadowy words in my head, watchin' the other's periodically black out here and there. It was madness! We would have been done for if not for the damned monkey."] = "0c9010e208fa0e5318f1df6b031376d3",
		["What's there to ask? He's a monkey you crazy fool. Anyhow, so yea, the monkey went into a frenzy after seein' ol' Brann flop into the sand face first. Nothin' the night elf could do was stopping Glibb here from poundin' on her noggin."] = "4419b499451d23fb555f4bbd5d1f3c98",
		["I'll tell you 'then what.' She went runnin' straight for the hive. And you know what's crazier? Not a single damned bug got in her way or tried to stop her. She ran through them all as if she'd been best friends with 'em for centuries."] = "c0ef1cc2e7bf63b3d68034c42fac68b9",
		["Yep."] = "bdd49ea534b3881187f934c773214283"
	},
	["Calandrath"] = {
		["Greetings, traveler. As long as you remain within the walls of the Cenarion Hold, you will be safe from harm.$B$BBe wary when leaving the protection of the Hold as the silithid have been swarming as of late."] = "aa4d909db480c4f692905dd5b95a455a"
	},
	["Khur Hornstriker"] = {
		["I supply the Hold with various relics required for spellcasting as well as other alchemical reagents."] = "3407714a9aac3f0bbd78877a9a9f2f09"
	},
	["Vargus"] = {
		["A great evil stirs, $r. Can you feel it?$B$BBah! Of course you cannot. Hand me your armor and weapons and I shall renew their vigor."] = "8df70dd608a3c4cf651cb64b15114023"
	},
	["Cloud Skydancer"] = {
		["Where would you like to fly to?"] = "8ee9e2b8b1fbeba82851331d36cb251c"
	},
	["Runk Windtamer"] = {
		["Where would you like to fly to?"] = "008491a7c8f31e3556f00e8c3fdc3190"
	},
	["Mishta"] = {
		["Oh dear, I am running dangerously low on supplies! What is taking that blasted goblin so long?"] = "adf109156d6688b93880917b0f179b65"
	},
	["Baristolth of the Shifting Sands"] = {
		["Look behind you, $r. The hive stirs as the land that surrounds us shudders and shakes.$B$BThe time has come for me to fulfill a promise I made a thousand years past. The sands shift once more as the Qiraji plan for war."] = "07d02c622457ae7e03cc05e5aefbc6e6"
	},
	["Commander Mar'alith"] = {
		["Why now, $r? I just do not understand it. So much work to be done..."] = "45ecbb32f065f665b991c1a4db9e7395"
	},
	["Vish Kozus"] = {
		["The Commander has not been himself as of late. His mistress disappeared while on an archaeological dig in the southern desert - vanished without a trace! Very strange, indeed.$B$BI suppose you're looking for work? Do I need to bash you in the head with a clue?"] = "b60ac134e16be202debcce1733994a3f"
	},
	["Geologist Larksbane"] = {
		["Can ye hear it, stranger? The humming is gettin' louder with each passing day. These crystals must be what's driving these bugs crazy."] = "923b9f247d112d5c467bec4f859d29b2"
	},
	["Cenarion Emissary Blackhoof"] = {
		["Are you here to help the cause? Mount Hyjal burns!"] = "43015d8ea437fe66ab83ecfd5e2acf22"
	},
	["Noggle Ficklespragg"] = {
		["Who are you?  Where am I?  I feel... so weak..."] = "4769fa7dbee7d466df239c3fdc15ce4d"
	},
	["Windcaller Proudhorn"] = {
		["Greetings, $c.  Welcome to Cenarion Hold.  From here we will strike against the silithid where they're at their strongest.  I hope you've come to lend a hand."] = "602ace4ed716eca72ea8d2e7882f4a76"
	},
	["Anachronos"] = {
		["It is we who must make the first strike. We cannot be allowed to repeat the mistakes of the past..."] = "a9f22c5df4d63c6e4bedddf079001171"
	},
	["Hermit Ortell"] = {
		["Leave at once, stranger!  I have no business with you."] = "e79d5d1fab3e655e71f596369ca816fa"
	},
	["Huum Wildmane"] = {
		["The spirits of Silithus call out to us, $n.  The land weeps, for it has a woeful story to tell..."] = "81fa3f4ee4a97d65004b878d5bb8a931"
	},
	["Aurel Goldleaf"] = {
		["The Cenarion Circle is wise, and has delved into many of earth's secrets.  Craftsmen would do well to heed the words of these druids."] = "43c3056caad01325e42ca64695ace0f9"
	},
	["Aendel Windspear"] = {
		["The ghostly figure looks at you with mistrust in her eyes and remains silent."] = "7e5673843945c43775f281baa44b09dc"
	},
	["Maxima Blastenheimer"] = {
		["Welcome! Step right up, don't be shy.$b$bThis here is my pride and joy... the Blastenheimer 5000 Ultra Cannon! Ain't she pretty?"] = "8b36145f2c1c61acdcb812a24ef1e381"
	},
	["Bor Wildmane"] = {
		["We have more than one enemy in Silithus, $n.$B$BWhile everyone's attention is focused on the silithid, my big brother and I have been keeping a close eye on the Twilight's Hammer crazies. "] = "ce744579ce13579a60435888a3801d63",
		["I get reports of your exploits against the Abyssal Council all the time, $n.  You're doing great things out there!$B$BKeep it up, and we'll make it worth the effort!"] = "8c5995e4b97669ab55bd426c84265ada"
	},
	["Horde Warbringer"] = {
		["War is upon us, $n.  It's time for every member of the Horde to answer the call and join the fight against the cowardly Alliance."] = "500674c7da105457382c51908165838f"
	},
	["Alliance Brigadier General"] = {
		["The war against the Horde has reached full tilt, $n.  This is a time of great need for the Alliance and it's necessary that all of us do our part to help."] = "d81a6dc390c1c398a8501dd7c88609ba"
	},
	["Merithra of the Dream"] = {
		["Heroes of the Brood? C'Thun must be banished! We can assist you, mortal!"] = "551053135aaeda0cc02c093df00e1973",
		["All will know of what has transpired here in this accursed temple, hero. It will be written about in history books - the tales told as legend from Azeroth to the far reaches of the Nether itself!"] = "27a21efbb42166d015d42aea8c63230d"
	},
	["Caelestrasz"] = {
		["Even if you somehow managed to free us without defeating C'Thun, we would focus all of our powers to see the beast banished back to the hell from whence it came - AT ANY COST."] = "febc6c6f0212bb59db53fa246e390a6c",
		["Our freedom would have meant nothing if C'Thun had survived. You are truly a champion of prophecy."] = "4a3616c5c52ca099ad816dfc278bf7a9"
	},
	["Arygos"] = {
		["I bear witness to a miracle that stands before me! In one thousand years of captivity, I have not seen a single LIVING specimen - other than those foul Qiraji and silithid - enter these chambers."] = "fbec45aaafa3ad165557bf6abbdc4ac2",
		["The world is indebted to you and your allies, $n."] = "fd10ddbf850f23ec3e5ca81dbb183556"
	},
	["Nafien"] = {
		["Only those who have proven themselves to not be hostile toward the Timbermaw may pass through the Hold without fear of being attacked.  Have you made an effort to earn our trust, outsider?"] = "a44f0bb1a217bc2dfd7ef659d46d08e1"
	},
	["Janela Stouthammer"] = {
		["Hail, $c.  The Ironforge Brigade is stationed here to keep an eye on Hive'Zora.  The Cenarion Circle druids have been monitoring silithid movement and they're anticipating something major in this area."] = "cea4e3e3ab05b82e1f49619ce41d48d8"
	},
	["Lieutenant General Andorov"] = {
		["<Andorov looks at you grimly.>$B$BIf it bleeds, we can kill it."] = "cbb32bb2891d6e835c05709df5717dc5",
		["We're on orders from on high to destroy Rajaxx. Terminate with extreme prejudice if you want to get technical."] = "be87bb665e714cf5287fbe8c435d1e40",
		["My mission is compete. I may have some spare supplies if you need any."] = "d09c2d999e65b1448ae55d611099958c"
	},
	["Spirit of Azuregos"] = {
		["My watch is eternal, mortal."] = "2bf0e3648b26738a7bf6e7d7823be52f",
		["You seek the scepter shard charged to the protection of the Blue Flight?$B$B<Azuregos appears to be smiling.>"] = "9e7b7b42e1613cdf4dcfa1f37fc77d00",
		["Shouldn't you be saving the world?"] = "377bf4ef63e885a98f3dd1ca83cf8ec6",
		["Of course I do not have the shard. That would be asinine. I walk amongst savages in this cursed land! I cannot take five steps without some crazed orc or human trying to thrust a sharp stick into my hide. At any given time you could very well be speaking to my ghostly spirit.$B$BAnyhow... I hid it.$B$BGo on... ask me where."] = "2e13942ba6f94b995534216cf82418e6",
		["You are going to love this story, $r. See, here is the thing. As soon as Malygos charged me with protecting the scepter shard, I knew I was in for an eternity of headache and pain.$B$BAll I want to do is study these magic rich shorelines and take in what artifacts might remain from the Sundering. You know, there was once a thriving Highborne civilization here! You don't have to tell me that there is going to be some solid magical items around here, $r. I can smell it!"] = "436488639e2cc3ae4ac47da206b71b83",
		["As I was saying, I held onto that scepter shard for a good five-hundred years and it was nothing but trouble. It attracted all kinds of attention - the wrong kind of attention. I want to be left alone to my studies not babysit some would be hero's ticket to glory. So... I gave it to the fish."] = "3dc5c0e4b351c5b64aa819d5d3928aba",
		["Not just any fish, mortal. This fish was a minnow. A very special minnow."] = "367122b574ac17ee8c68648a02b55f90",
		["Exactly!"] = "5b20ac7c020d0194210227d8a836bfa4",
		["Genius, I know... It will never be found; but, in case it is found, I gave the minnow some special powers."] = "7f5c4f2e3a2697a63865d73319874c62",
		["Correct. You've been listening! This minnow is really quite a terrible creature of my own creation. When I am relaxing I like to think of the unlucky fishermen who have run into this minnow and been devoured whole. I bet they were quite surprised!$B$B<Azuregos laughs.>"] = "c57635a8260cecfb9be646d8a45a9182",
		["Genius is often misunderstood, $r. Now, about the scepter shard... If you want that shard and do not wish to spend the next ten thousand years searching for it, you are going to have to listen very carefully."] = "eda9a414e72f86503ee048b63c667de5",
		["Two words: Arcanite buoy."] = "7c287ab602a7e14a1fb9f3f5bc42af9b",
		["Right then... You have to build an arcanite buoy and place it in the ocean. My minnow will be attracted to the magical emanations. When he gets near the buoy - BLAMO! It will explode in a glorious pulse of arcane energy, revealing the minnow's true form. Also, you may or may not incur the wrath of Neptulon. A 50/50 chance I would say."] = "7a556295fa58d581ede3422f364006c5",
		["If I did not know better I would think that you were mocking me, mortal; but yes, that is mostly correct. You may remain fully clothed."] = "ac823cafc6ef807803856a24f4a9ca95",
		["Take this ledger to an old acquaintance of mine in Tanaris. His name is Narain Soothfancy - terrible, terrible, psychic but an amazing engineer! He should be able to make sense of it all.$B$BNo need to thank me, $n. It's the least I could do.$B$BGood day!"] = "599ef7db0afb6ffa75db3a2fb50f7f28"
	},
	["Windcaller Yessendra"] = {
		["Our steady progress in our fight against the Qiraji can be attributed to the diverse help we received from nearly every corner of Kalimdor.$B$BYou need more than just soldiers to fight a war, $n.  Many of the war's unsung heroes are the traders and craftsmen that keep our forces supplied with the resources they need."] = "b3799b82bc9ff1942e4ac19ba2d4c105"
	},
	["Warden Haro"] = {
		["I, like many others, came to aid my fellow druids when the war started.$B$BNow that the Gates of Ahn'Qiraj are open, I've realized that much work still remains to be done.  I've decided to stay in Silithus and do my best to help the cause, $n.  "] = "5ad93a4745aa099f6c0236880ca96ae9"
	},
	["Keyl Swiftclaw"] = {
		["This war's not over, it's only just begun!  We have brave men and women fighting our enemy inside Ahn'Qiraj day and night, $n.  It won't be long before the Qiraji city falls."] = "814445cc1ab4e2c8f95a5e1a409c5970"
	},
	["Andorgos"] = {
		["Step carefully mortal.  You tread where mightier beings have met their fate."] = "01a72b8a9ee3737b37605b3e99d6402a",
		["With the Emperors slain, the magical protection blocking teleportation within the temple has been greatly weakened. If you desire, I am able to translocate you to the Emperors' lair."] = "e3ba53c521b1009ced105bc09ff00136",
		["With Ouro slain the way is clear to the final chamber. I am able to transport you there, if you desire."] = "2e604774c5428e55d30448b3f9443e9b"
	},
	["Kandrostrasz"] = {
		["A thousand years ago, when the War of the Shifting Sands ended, three of our kin sacrificed themselves and held the Qiraji inside these halls while Anachronos and Staghelm sealed Ahn'Qiraj shut.$B$BEach of us vowed to look for Merithra, Arygos and Caelestrasz should the Scarab Wall ever fall.$B$BAnd fall it did... and so we came."] = "60e14cbaa8435b4075f83aeb3e80dcff"
	},
	["Vethsera"] = {
		["An unspeakable horror dwells here, mortal.  C'Thun and his worshippers are not just an affront to nature, their existence presages destruction for Azeroth as we know it.$B$BMerithra sacrificed herself a thousand years ago along with Caelestrasz and Arygos because they knew this as well.  We're here because of our oath to return for them, but we're also here because C'Thun must be stopped!"] = "0256593f191b79bf991a495678be7dce"
	},
	["Meridith the Mermaiden"] = {
		["It's so lovely to see you again, $n! I really can't thank you enough for delivering that message to my dear little gnome.$B$BWould you like to hear a song? It will make traveling in the rough seas much easier!"] = "fdd0891a6be06b63cd5dbb71f1d437cb",
		["I find the ocean floor to be very peaceful."] = "4e3aaa281117f3fae81170f3a6b3a244"
	},
	["Windcaller Kaldon"] = {
		["Now that the war is in full swing, we've had no shortage of able-bodied combatants from the Horde and Alliance.$B$BIf only we could keep them off of each other's throats..."] = "d3444f4b56739837e99b8054c798a837"
	},
	["Elder Morndeep"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Ironband lives in Blackchar Cave in Searing Gorge."] = "6954eeb9a527a8cef8cc62722874280a"
	},
	["Elder Splitrock"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["You'll find Elder Grimtotem at the Lariss Pavilion in Feralas."] = "63b174e10f467641f0509f5e8838c7e0",
		["Elder Mistwalker enjoys watching the struggles at the Maul in Feralas."] = "318ed0e744f88da539e3c51bc4697212"
	},
	["Elder Rumblerock"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Dawnstrider can be found at Flame Crest on the Burning Steppes."] = "a82acbf9cc59e1d9b14eec0cc0cef377",
		["Elder Hammershout can be found outside the walls of Stormwind."] = "6c995fbb58dbb24f0e8596945d185944",
		["Elder Stormbrow is most likely at the village of Goldshire in Elwynn Forest."] = "0ef3a4daeaac64acf2ca98fcf3350b69",
		["Winterhoof? I hear he's living it up in Booty Bay."] = "37a1c67b2928272c30a2e3b3821eadc1"
	},
	["Elder Silvervein"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Goldwell spends his time in the village of Kharanos in Dun Morogh."] = "11ccf478d11d91ad3de1ce0965dd1e7c",
		["Elder Ironband lives in Blackchar Cave in Searing Gorge."] = "6954eeb9a527a8cef8cc62722874280a"
	},
	["Elder Highpeak"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Moonstrike can be found in the Scholomance in the Western Plaguelands."] = "969acaf245ed6f2b05bdbb672a4a18c9"
	},
	["Elder Stonefort"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Ironband lives in Blackchar Cave in Searing Gorge."] = "6954eeb9a527a8cef8cc62722874280a"
	},
	["Elder Obsidian"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Graveborn spends time near Brill in Tirisfal Glades."] = "8aa7da319f4642917680c8b017576c28",
		["Elder Highpeak watches over the Hinterlands from a hill near its center."] = "caf07620c72127b10e1729b5a72eef6b",
		["Elder Moonstrike can be found in the Scholomance in the Western Plaguelands."] = "969acaf245ed6f2b05bdbb672a4a18c9"
	},
	["Elder Hammershout"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Bladeswift wanders the paths of Darnassus atop Teldrassil."] = "7b97edf23dc2c013612ec1169de003d7",
		["Elder Bronzebeard can be found in the ancestral home of the Bronzebeards, Ironforge."] = "f65717b9ef7e2cce484130fee81dd53a",
		["Elder Rumblerock passes the years in a cave atop Dreadmaul Rock in the Burning Steppes."] = "9f8adafc093f04bb044f1e110b7ea3ac",
		["Elder Stormbrow is most likely at the village of Goldshire in Elwynn Forest."] = "0ef3a4daeaac64acf2ca98fcf3350b69"
	},
	["Elder Bellowrage"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Last I knew, Elder Starsong was in the Sunken Temple of the Swamp of Sorrows."] = "4c3e419f5e2712f60d981727a7b7fb3d"
	},
	["Elder Darkcore"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["In days long past, we lived for the hunt.  We hunted for glory, for honor...$B$BIs it so different now?"] = "4e97e0f163a9aef48d77bb844db92cf4",
		["Elder Graveborn spends time near Brill in Tirisfal Glades."] = "8aa7da319f4642917680c8b017576c28",
		["Elder Ironband lives in Blackchar Cave in Searing Gorge."] = "6954eeb9a527a8cef8cc62722874280a",
		["Elder Moonstrike can be found in the Scholomance in the Western Plaguelands."] = "969acaf245ed6f2b05bdbb672a4a18c9",
		["Elder Wheathoof is enjoying the vistas above Mulgore at Thunder Bluff."] = "1b109a6a10e600d1d61b57bb67ccbc7b",
		["Elder Darkcore can be found in the Undercity."] = "65ed32ee792501359c944e9da3ef350e",
		["Last I heard, Elder Runetotem was traveling to Razor Hill in Durotar."] = "fc261962363f24c704ac8db7ceea85ba",
		["Elder Windtotem is keeping company with the goblins of Ratchet on the coast of the Barrens."] = "98b25a10e22df39903c715f1efdbf3f9"
	},
	["Elder Stormbrow"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Hammershout can be found outside the walls of Stormwind."] = "6c995fbb58dbb24f0e8596945d185944",
		["Elder Rumblerock passes the years in a cave atop Dreadmaul Rock in the Burning Steppes."] = "9f8adafc093f04bb044f1e110b7ea3ac",
		["Elder Skychaser looks out over Westfall from atop Sentinel Hill."] = "e651b39f5ae6f7809f65b90f78c4d124",
		["Last I knew, Elder Starsong was in the Sunken Temple of the Swamp of Sorrows."] = "4c3e419f5e2712f60d981727a7b7fb3d"
	},
	["Elder Snowcrown"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Graveborn spends time near Brill in Tirisfal Glades."] = "8aa7da319f4642917680c8b017576c28",
		["Elder Farwhisper can be found wandering the streets of Stratholme."] = "0183522424d4cfa55625a193ad8eb384",
		["I last saw Elder Meadowrun at the Weeping Cave in the Western Plaguelands."] = "9561bb678055b9a1834b829d760f2648",
		["Elder Moonstrike can be found in the Scholomance in the Western Plaguelands."] = "969acaf245ed6f2b05bdbb672a4a18c9",
		["Elder Windrun resides in the Crown Guard Tower in the Eastern Plaguelands."] = "1167586aae0013970f4f9115b9fbb868"
	},
	["Elder Ironband"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Bronzebeard can be found in the ancestral home of the Bronzebeards, Ironforge."] = "f65717b9ef7e2cce484130fee81dd53a",
		["Elder Goldwell spends his time in the village of Kharanos in Dun Morogh."] = "11ccf478d11d91ad3de1ce0965dd1e7c",
