	},
	["Elder Goldwell"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["Elder Bronzebeard can be found in the ancestral home of the Bronzebeards, Ironforge."] = "f65717b9ef7e2cce484130fee81dd53a",
		["Elder Ironband lives in Blackchar Cave in Searing Gorge."] = "6954eeb9a527a8cef8cc62722874280a",
		["Elder Silvervein can be found near Thelsamar in Loch Modan."] = "65bd0e4bec11189bc9ac50bd03e9d0f4"
	},
	["Elder Primestone"] = {
		["Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["If you travel to Cenarion Hold in Silithus, you will find Elder Bladesing."] = "803c8ecb73eec2056dde8e33f84c9105",
		["For reasons I cannot understand, Elder Thunderhorn has gone to the Slithering Scar in Un'Goro Crater."] = "ec66e93d5033de66fd54fb9f825190c5"
	},
	["Elder Runetotem"] = {
